import json
import requests
from typing import Any, Dict, List

class AWSCore:
    def __init__(self, region: str, endpoint: str = None):
        self.region = region
        self.endpoint = endpoint or 'https://api.us-east-1.amazonaws.com'

    def _build_url(self, service: str, method: str, path: str, params: Dict[str, Any] = None) -> str:
        url = f'{self.endpoint}/{self.region}/{service}/{method}'
        if path:
            url += '/' + path
        if params:
            url += '?' + '&'.join(f'{k}={v}' for k, v in params.items())
        return url

    def _http_request(self, method: str, url: str, body: Dict[str, Any] = None, headers: Dict[str, str] = None) -> requests.Response:
        response = requests.request(method, url, json=body, headers=headers)
        response.raise_for_status()
        return response

    def _get(self, service: str, path: str, params: Dict[str, Any] = None) -> requests.Response:
        url = self._build_url(service, 'GET', path, params)
        return self._http_request('GET', url)

    def _post(self, service: str, path: str, body: Dict[str, Any] = None, headers: Dict[str, str] = None) -> requests.Response:
        url = self._build_url(service, 'POST', path, body)
        return self._http_request('POST', url, body, headers)

    def get(self, service: str, path: str, params: Dict[str, Any] = None) -> Dict[str, Any]:
        response = self._get(service, path, params)
        return response.json()

    def post(self, service: str, path: str, body: Dict[str, Any] = None, headers: Dict[str, str] = None) -> Dict[str, Any]:
        response = self._post(service, path, body, headers)
        return response.json()

# Example usage:
core = AWSCore('us-east-1')
response = core.post('lambda', '2014-11-05', {'functionName': 'my-function'})
print(response)
