import pip

def install_package(package_name):
    try:
        pip.main(['install', package_name])
        print(f"Package {package_name} installed successfully.")
    except Exception as e:
        print(f"Failed to install package {package_name}: {e}")

def upgrade_packages():
    try:
        pip.main(['upgrade'])
        print("All packages upgraded successfully.")
    except Exception as e:
        print(f"Failed to upgrade packages: {e}")

def uninstall_package(package_name):
    try:
        pip.main(['uninstall', package_name])
        print(f"Package {package_name} uninstalled successfully.")
    except Exception as e:
        print(f"Failed to uninstall package {package_name}: {e}")

def main():
    while True:
        print("\n1. Install Package")
        print("2. Upgrade Packages")
        print("3. Uninstall Package")
        print("4. Quit")

        choice = input("Enter your choice: ")

        if choice == "1":
            package_name = input("Enter the package name to install: ")
            install_package(package_name)
        elif choice == "2":
            upgrade_packages()
        elif choice == "3":
            package_name = input("Enter the package name to uninstall: ")
            uninstall_package(package_name)
        elif choice == "4":
            break
        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
    main()
