import idna

def idna_encode(domain_name):
    try:
        return idna.encode(domain_name, allow_unassigned=True)
    except idna.IDNAError as e:
        return f"Invalid IDNA encoding: {e}"

def idna_decode(ascii_domain_name):
    try:
        return idna.decode(ascii_domain_name)
    except idna.IDNAError as e:
        return f"Invalid IDNA decoding: {e}"

# Example usage:
domain_name = "example.com"
ascii_domain_name = idna_encode(domain_name)
print(f"IDNA encoded domain name: {ascii_domain_name}")

# Validation
try:
    idna.decode(domain_name)
    print("Domain name is valid for IDNA encoding.")
except idna.IDNAError:
    print("Domain name is not valid for IDNA encoding.")

# Decoding
try:
    idna.decode(ascii_domain_name)
    print("IDNA decoded domain name is valid.")
except idna.IDNAError:
    print("IDNA decoded domain name is not valid.")
