import boto3
from botocore.exceptions import NoCredentialsError

class S3TransferManager:
    def __init__(self, bucket_name, local_path):
        self.bucket_name = bucket_name
        self.local_path = local_path
        self.s3 = boto3.client('s3')

    def upload_file(self, local_file_path):
        try:
            self.s3.upload_file(local_file_path, self.bucket_name, local_file_path.split('/')[-1])
            print(f"File {local_file_path} uploaded to {self.bucket_name}")
        except FileNotFoundError:
            print(f"File {local_file_path} not found")
        except NoCredentialsError:
            print("Credentials not available")

    def download_file(self, remote_file_path):
        try:
            self.s3.download_file(self.bucket_name, remote_file_path, self.local_path)
            print(f"File {remote_file_path} downloaded to {self.local_path}")
        except FileNotFoundError:
            print(f"File {self.local_path} not found")
        except NoCredentialsError:
            print("Credentials not available")

# Example usage
if __name__ == "__main__":
    bucket_name = 'your-bucket-name'
    local_path = '/path/to/local/file'
    remote_file_path = 'file.txt'

    s3_transfer_manager = S3TransferManager(bucket_name, local_path)
    s3_transfer_manager.upload_file(local_path)
    s3_transfer_manager.download_file(remote_file_path)
