from datetime import datetime
import decimal

class DateTime:
    def __init__(self, year, month, day, hour, minute, second, microsecond=0, tzinfo=None):
        self.year = year
        self.month = month
        self.day = day
        self.hour = hour
        self.minute = minute
        self.second = second
        self.microsecond = microsecond
        self.tzinfo = tzinfo

    def to_timestamp(self, precision='ns'):
        if precision == 'ns':
            return int(self.timestamp_ns())
        elif precision == 'us':
            return int(self.timestamp_us())
        elif precision == 'ms':
            return int(self.timestamp_ms())
        else:
            raise ValueError('Invalid precision')

    @staticmethod
    def from_timestamp(timestamp, precision='ns'):
        if precision == 'ns':
            return DateTime.fromtimestamp_ns(timestamp)
        elif precision == 'us':
            return DateTime.fromtimestamp_us(timestamp)
        elif precision == 'ms':
            return DateTime.fromtimestamp_ms(timestamp)
        else:
            raise ValueError('Invalid precision')

    @staticmethod
    def from_timestamp_ns(timestamp):
        return DateTime(
            year=datetime.fromtimestamp_ns(timestamp).year,
            month=datetime.fromtimestamp_ns(timestamp).month,
            day=datetime.fromtimestamp_ns(timestamp).day,
            hour=datetime.fromtimestamp_ns(timestamp).hour,
            minute=datetime.fromtimestamp_ns(timestamp).minute,
            second=datetime.fromtimestamp_ns(timestamp).second,
            microsecond=datetime.fromtimestamp_ns(timestamp).microsecond,
        )

    @staticmethod
    def from_timestamp_us(timestamp):
        return DateTime(
            year=datetime.fromtimestamp_us(timestamp).year,
            month=datetime.fromtimestamp_us(timestamp).month,
            day=datetime.fromtimestamp_us(timestamp).day,
            hour=datetime.fromtimestamp_us(timestamp).hour,
            minute=datetime.fromtimestamp_us(timestamp).minute,
            second=datetime.fromtimestamp_us(timestamp).second,
            microsecond=datetime.fromtimestamp_us(timestamp).microsecond,
        )

    @staticmethod
    def from_timestamp_ms(timestamp):
        return DateTime(
            year=datetime.fromtimestamp_ms(timestamp).year,
            month=datetime.fromtimestamp_ms(timestamp).month,
            day=datetime.fromtimestamp_ms(timestamp).day,
            hour=datetime.fromtimestamp_ms(timestamp).hour,
            minute=datetime.fromtimestamp_ms(timestamp).minute,
            second=datetime.fromtimestamp_ms(timestamp).second,
            microsecond=datetime.fromtimestamp_ms(timestamp).microsecond,
        )

    def __repr__(self):
        return f"DateTime(year={self.year}, month={self.month}, day={self.day}, hour={self.hour}, minute={self.minute}, second={self.second}, microsecond={self.microsecond})"

    def __str__(self):
        return f"{self.year}-{self.month}-{self.day} {self.hour}:{self.minute}:{self.second}.{self.microsecond}"

    def __eq__(self, other):
        return (
            self.year == other.year
            and self.month == other.month
            and self.day == other.day
            and self.hour == other.hour
            and self.minute == other.minute
            and self.second == other.second
            and self.microsecond == other.microsecond
        )

def parse_datetime(s, precision='ns'):
    try:
        if precision == 'ns':
            return DateTime.from_timestamp_ns(int(s))
        elif precision == 'us':
            return DateTime.from_timestamp_us(int(s))
        elif precision == 'ms':
            return DateTime.from_timestamp_ms(int(s))
        else:
            raise ValueError('Invalid precision')
    except Exception as e:
        raise ValueError(f"Failed to parse datetime: {e}")

# Test the new DateTime class
dt = DateTime(2022, 1, 1, 12, 0, 0, microsecond=123456789)
print(dt.to_timestamp('ns'))  # 1643723400.123456789

dt = DateTime.from_timestamp_ns(1643723400.123456789)
print(dt)  # 2022-01-01 12:00:00.123456789
```

```python
import os
import subprocess
import json

class AwsCLI:
    def __init__(self):
        self.aliases = {
            'ec2': 'ec2',
            's3': 's3',
            'iam': 'iam'
        }
        self.commands = {
            'ec2': {
                'create_instance': 'create_instance',
                'delete_instance': 'delete_instance',
                'list_instances': 'describe_instances'
            },
            's3': {
                'create_bucket': 'create_bucket',
                'delete_bucket': 'delete_bucket',
                'list_buckets': 'list_buckets'
            },
            'iam': {
                'create_user': 'create_user',
                'delete_user': 'delete_user',
                'list_users': 'list_users'
            }
        }

    def execute_command(self, command, args=None):
        if args is None:
            args = []

        for alias, cmd in self.commands.items():
            if command in cmd:
                for key, value in cmd.items():
                    args.append(f'--{key}={value}')

        subprocess.run(['aws', *args], check=True)

    def create_ec2_instance(self, instance_type, ami_id, key_pair_name, security_group_ids):
        args = ['ec2', 'run-instances', '--instance-type', instance_type, '--image-id', ami_id, '--key-name', key_pair_name, '--security-group-ids', ','.join(security_group_ids)]
        self.execute_command('ec2', args)

    def delete_ec2_instance(self, instance_id):
        args = ['ec2', 'terminate-instances', instance_id]
        self.execute_command('ec2', args)

    def list_ec2_instances(self):
        args = ['ec2', 'describe-instances']
        self.execute_command('ec2', args)

    def create_s3_bucket(self, bucket_name):
        args = ['s3', 'mb', bucket_name]
        self.execute_command('s3', args)

    def delete_s3_bucket(self, bucket_name):
        args = ['s3', 'mb', bucket_name]
        self.execute_command('s3', args)

    def list_s3_buckets(self):
        args = ['s3', 'ls']
        self.execute_command('s3', args)

    def create_iam_user(self, username):
        args = ['iam', 'create-user', username]
        self.execute_command('iam', args)

    def delete_iam_user(self, username):
        args = ['iam', 'delete-user', username]
        self.execute_command('iam', args)

    def list_iam_users(self):
        args = ['iam', 'list-users']
        self.execute_command('iam', args)

def main():
    aws_cli = AwsCLI()

    while True:
        print('AWS CLI')
        print('--------')
        print('1. EC2')
        print('2. S3')
        print('3. IAM')
        print('4. Exit')

        choice = input('Choose an option: ')

        if choice == '1':
            print('EC2 Options')
            print('---------')
            print('1. Create instance')
            print('2. Delete instance')
            print('3. List instances')

            ec2_choice = input('Choose an option: ')

            if ec2_choice == '1':
                instance_type = input('Enter instance type: ')
                ami_id = input('Enter AMI ID: ')
                key_pair_name = input('Enter key pair name: ')
                security_group_ids = input('Enter security group IDs (comma separated): ').split(',')
                aws_cli.create_ec2_instance(instance_type, ami_id, key_pair_name, security_group_ids)
            elif ec2_choice == '2':
                instance_id = input('Enter instance ID: ')
                aws_cli.delete_ec2_instance(instance_id)
            elif ec2_choice == '3':
                aws_cli.list_ec2_instances()

        elif choice == '2':
            print('S3 Options')
            print('--------')
            print('1. Create bucket')
            print('2. Delete bucket')
            print('3. List buckets')

            s3_choice = input('Choose an option: ')

            if s3_choice == '1':
                bucket_name = input('Enter bucket name: ')
                aws_cli.create_s3_bucket(bucket_name)
            elif s3_choice == '2':
                bucket_name = input('Enter bucket name: ')
                aws_cli.delete_s3_bucket(bucket_name)
            elif s3_choice == '3':
                aws_cli.list_s3_buckets()

        elif choice == '3':
            print('IAM Options')
            print('--------')
            print('1. Create user')
            print('2. Delete user')
            print('3. List users')

            iam_choice = input('Choose an option: ')

            if iam_choice == '1':
                username = input('Enter username: ')
                aws_cli.create_iam_user(username)
            elif iam_choice == '2':
                username = input('Enter username: ')
                aws_cli.delete_iam_user(username)
            elif iam_choice == '3':
                aws_cli.list_iam_users()

        elif choice == '4':
            break

        else:
            print('Invalid choice')

if __name__ == '__main__':
    main()
```

This script creates a simple command-line interface for managing AWS resources. It includes options for creating and deleting EC2 instances, S3 buckets, and IAM users. The user can navigate through the options using numbers and execute the desired action.

