import struct

# ASN.1 Type Enum
class ASN1Type:
    INT = 0
    OCTET_STRING = 1
    SEQUENCE = 2
    SET = 3
    CHOICE = 4
    ANY = 5

# ASN.1 Type Definition
class ASN1TypeDefinition:
    def __init__(self, tag, type):
        self.tag = tag
        self.type = type

    def to_der(self):
        return struct.pack('!H', self.tag) + struct.pack('!B', self.type)

# DER Encoding
def der_encode(value, type_definition):
    if type_definition.type == ASN1Type.SET:
        return b''.join(der_encode(v, t) for v, t in zip(value, type_definition.type))
    elif type_definition.type == ASN1Type CHOICE:
        return b''.join(der_encode(v, t) for v, t in zip(value, type_definition.type))
    else:
        return struct.pack('!B', value) + der_encode(type_definition.type, type_definition)

# BER Encoding
def ber_encode(value, type_definition):
    if type_definition.type == ASN1Type.OCTET_STRING:
        return b''.join(struct.pack('!B', v) for v in value)
    elif type_definition.type == ASN1Type.SEQUENCE:
        return struct.pack('!B', len(value)) + b''.join(ber_encode(v, t) for v, t in zip(value, type_definition.type))
    else:
        return struct.pack('!B', value)

# CER Encoding
def cer_encode(value, type_definition):
    return b''.join(der_encode(v, t) for v, t in zip(value, type_definition.type))

# Example Usage:
type_def = ASN1TypeDefinition(0x30, [ASN1TypeDefinition(0x05, ASN1Type.OCTET_STRING), ASN1TypeDefinition(0x03, ASN1Type.OCTET_STRING)])
value = [b'Hello', b'World']

der_encoded = der_encode(value, type_def)
ber_encoded = ber_encode(value, type_def)
cer_encoded = cer_encode(value, type_def)

print(der_encoded)
print(ber_encoded)
print(cer_encoded)
```

