```python
class TemplateNode:
    def __init__(self, type, value):
        self.type = type
        self.value = value
        self.children = []

class TemplateEngine:
    def __init__(self):
        self.root = None

    def parse_template(self, template_str):
        nodes = []
        current_node = None
        for char in template_str:
            if char == '{':
                if current_node is None:
                    current_node = TemplateNode('block', '')
                else:
                    current_node.children.append(TemplateNode('block', ''))
            elif char == '}':
                if current_node is not None:
                    nodes.append(current_node)
                    current_node = None
            elif char == '%':
                if current_node is None:
                    current_node = TemplateNode('inline', '')
                else:
                    current_node.children.append(TemplateNode('inline', ''))
            elif char == '{' and current_node is not None:
                current_node.children.append(TemplateNode('block', ''))
            elif char == '%' and current_node is not None:
                current_node.children.append(TemplateNode('inline', ''))
        if current_node is not None:
            nodes.append(current_node)

        return nodes

    def render(self, template_str, context):
        nodes = self.parse_template(template_str)
        def render_node(node, context):
            if node.type == 'block':
                for child in node.children:
                    render_node(child, context)
                return self.render_block(child, context)
            elif node.type == 'inline':
                return self.render_inline(child, context)
            else:
                raise ValueError(f"Invalid node type: {node.type}")

        def render_block(node, context):
            if node.value == '':
                return ''
            if node.value.startswith('{'):
                return render_block(TemplateNode('block', node.value[1:-1]), context)
            elif node.value.startswith('%'):
                return render_inline(TemplateNode('inline', node.value[1:-1]), context)
            else:
                return node.value

        def render_inline(node, context):
            if node.value == '':
                return ''
            if node.value.startswith('{'):
                return render_block(TemplateNode('block', node.value[1:-1]), context)
            elif node.value.startswith('%'):
                return render_inline(TemplateNode('inline', node.value[1:-1]), context)
            else:
                return node.value.replace('{{', '{').replace('}}', '}')

        result = render_node(nodes[0], context)
        return result

# Example usage
engine = TemplateEngine()
template_str = '{% if user %}{% block content %}{% for item in items %}{{ item }}{% endfor %}{% endblock %}{% endif %}'
context = {'user': True, 'items': ['item1', 'item2']}
print(engine.render(template_str, context))
