import argparse

class Command:
    def __init__(self, name, help=None):
        self.name = name
        self.help = help
        self.parser = None

    def add_parser(self, parser):
        if self.parser is not None:
            raise ValueError("Only one parser can be set for a command")
        self.parser = parser

    def run(self, args):
        if self.parser is None:
            raise ValueError("Parser not set for command")
        self.parser.parse_args(args)

class Parser(argparse.ArgumentParser):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.commands = {}

    def add_command(self, command):
        self.commands[command.name] = command
        command.add_parser(self)

class Workflow:
    def __init__(self, parser):
        self.parser = parser
        self.commands = {}

    def add_command(self, command):
        self.commands[command.name] = command
        command.add_parser(self.parser)

    def run(self, args):
        self.parser.parse_args(args)

def main():
    parser = Parser(description="My CLI")
    greet = Command("greet", help="Prints a greeting message")
    greet.add_parser(parser)

    hello = Command("hello", help="Prints a personalized greeting message")
    hello.add_parser(parser)

    workflow = Workflow(parser)
    workflow.add_command(greet)
    workflow.add_command(hello)

    parser.add_argument("-n", "--name", help="Your name")
    parser.add_argument("-m", "--message", help="Your message")

    args = parser.parse_args(["-h", "--help"])

    if args.name and args.message:
        print(f"Hello, {args.name}! Your message is: {args.message}")
    elif args.name:
        print(f"Hello, {args.name}!")
    elif args.message:
        print(f"Your message is: {args.message}")
    else:
        print("No arguments provided")

if __name__ == "__main__":
    main()
