from os import path
from shutil import which
from contextlib import contextmanager
import zipfile

class ZipPath:
    def __init__(self, zip_file):
        self.zip_file = zip_file

    @property
    def path(self):
        return path.basename(self.zip_file)

    @property
    def is_dir(self):
        return path.isfile(self.zip_file) and path.getsize(self.zip_file) > 0

    def __enter__(self):
        self.original_cwd = os.getcwd()
        os.chdir(path.dirname(self.zip_file))

    def __exit__(self, exc_type, exc_val, exc_tb):
        os.chdir(self.original_cwd)

@contextmanager
def zip_context(zip_file):
    if not path.isfile(zip_file):
        raise FileNotFoundError(f"The file '{zip_file}' does not exist.")
    if not zipfile.is_zipfile(zip_file):
        raise ValueError(f"'{zip_file}' is not a valid ZIP file.")
    yield ZipPath(zip_file)

# Usage:
with zip_context('path_to_your_zip_file.zip') as zip_path:
    print(zip_path.path)
    print(zip_path.is_dir)
