```python
class MemoizingCollection:
    def __init__(self):
        self.cache = {}

    def get(self, key):
        return self.cache.get(key)

    def set(self, key, value):
        self.cache[key] = value

    def invalidate(self, key):
        if key in self.cache:
            del self.cache[key]

    def __contains__(self, key):
        return key in self.cache

    def __len__(self):
        return len(self.cache)

    def __getitem__(self, key):
        return self.get(key)

    def __setitem__(self, key, value):
        self.set(key, value)

    def __delitem__(self, key):
        self.invalidate(key)

    def __iter__(self):
        return iter(self.cache.keys())

    def __repr__(self):
        return f'MemoizingCollection({self.cache})'


def memoize(func):
    cache = {}
    def memoized_func(*args):
        key = (args,)
        if key in cache:
            return cache[key]
        result = func(*args)
        cache[key] = result
        return result
    return memoized_func


# Example usage:
class MyClass:
    def __init__(self, value):
        self.value = value

    def my_method(self):
        # Simulate some computation
        import time
        time.sleep(1)
        return self.value * 2


my_class = MyClass(10)

memoized_my_class = memoize(my_class)

print(memoized_my_class(10).my_method())  # 20
print(memoized_my_class(10).my_method())  # 20
print(my_class(10).my_method())  # 20

# Invalidate the cache
my_class.value = 20
print(memoized_my_class(10).my_method())  # 40
```

