from PIL import Image

def open_image(file_path):
    try:
        img = Image.open(file_path)
        return img
    except FileNotFoundError:
        print("File not found.")
        return None
    except Exception as e:
        print("Error opening image:", str(e))
        return None

def save_image(img, file_path, format):
    try:
        img.save(file_path, format=format)
        return True
    except Exception as e:
        print("Error saving image:", str(e))
        return False

def manipulate_image(img):
    # Apply a 10% opacity effect to the image
    img.putalpha(128)

    # Resize the image to 50% of its original size
    img = img.resize((img.width // 2, img.height // 2))

    return img

def main():
    # Open an image file
    img = open_image('input.png')

    if img is not None:
        # Manipulate the image
        manipulated_img = manipulate_image(img)

        # Save the manipulated image
        save_image(manipulated_img, 'output.png', 'PNG')

if __name__ == "__main__":
    main()
