import asyncio
from asyncio import TimeoutError

async def async_timeout_context_manager(time_limit, func):
    try:
        await asyncio.wait_for(func(), timeout=time_limit)
    except asyncio.TimeoutError:
        raise TimeoutError(f"Function '{func.__name__}' timed out after {time_limit} seconds")

def timeout_context_manager(time_limit, func):
    loop = asyncio.get_event_loop()
    return loop.create_task(async_timeout_context_manager(time_limit, func))
