class URITemplate:
    def __init__(self, template):
        self.template = template

    def replace(self, values):
        for key, value in values.items():
            self.template = self.template.replace('{' + key + '}', value)
        return self.template

def parse_template(template):
    parts = template.split('/')
    uri_template = URITemplate(parts[0])
    params = {}
    for part in parts[1:]:
        key, value = part.split('?')
        key, value = value.split('#')
        params[key] = value
    return uri_template, params

def construct_template(uri_template, params):
    template = uri_template.template
    for key, value in params.items():
        template = template.replace('{' + key + '}', value)
    return template

class URI:
    def __init__(self, template, values=None):
        self.template = template
        self.values = values if values else {}

    def __str__(self):
        return self.template

    def replace(self):
        self.values = parse_template(self.template).pop()

    def __getitem__(self, key):
        self.replace()
        return self.values[key]

# Example usage:
template = 'https://example.com/{path}?lang={lang}&id={id}#fragment'
uri = URI(template, {'path': '/users', 'lang': 'en', 'id': '123'})
print(uri)  # Output: https://example.com/users?lang=en&id=123#fragment
uri.replace()
print(uri)  # Output: https://example.com/users?lang=en&id=123#fragment
print(uri['path'])  # Output: /users
print(uri['lang'])  # Output: en
print(uri['id'])  # Output: 123
```

