import numpy as np
import scipy.optimize as optimize

class CassowarySolver:
    def __init__(self, equations):
        self.equations = equations
        self.constraints = []

    def add_constraint(self, constraint):
        self.constraints.append(constraint)

    def solve(self):
        constraints = self.constraints
        variables = [list(self.equations[i].values())[0] for i in range(len(self.equations))]
        eqs = [list(self.equations[i].keys()) for i in range(len(self.equations))]

        def f(vars):
            result = []
            for i in range(len(eqs)):
                eq = eqs[i]
                result.append(sum([vars[j] * self.equations[i][j] for j in eq]))
            return result

        def g(vars):
            result = []
            for constraint in constraints:
                result.append(constraint(vars))
            return result

        res = optimize.least_squares(f, variables)
        if res.success:
            return res.x
        else:
            raise Exception("Failed to converge")

# Example usage:
class Equation:
    def __init__(self, name, func):
        self.name = name
        self.func = func

equations = [
    Equation('x+y', {'x': 1, 'y': 2}),
    Equation('x-2*y', {'x': 3, 'y': 4}),
]

solver = CassowarySolver(equations)
solver.add_constraint(lambda x: x[0] + x[1] - 5)

try:
    solution = solver.solve()
    print(solution)
except Exception as e:
    print(str(e))
