```python
import operator
from functools import reduce

def filter_iter(iterable, predicate):
    """Return an iterator that filters elements from the iterable based on a predicate function."""
    for element in iterable:
        if predicate(element):
            yield element

def groupby_iter(iterable, key=None):
    """Return an iterator that groups elements from the iterable based on a key function."""
    current_key = None
    current_group = []
    for element in iterable:
        k = key(element) if key else element
        if k != current_key:
            if current_group:
                yield current_key, list(current_group)
            current_key = k
            current_group = []
        current_group.append(element)
    if current_group:
        yield current_key, current_group

def map_iter(iterable, function):
    """Return an iterator that maps a function over the elements of the iterable."""
    for element in iterable:
        yield function(element)

def reduce_iter(iterable, function, initial=None):
    """Return the result of applying a function of two arguments cumulatively to the items of an iterable, 
    from left to right, so as to reduce the iterable to a single output."""
    it = iter(iterable)
    result = initial
    for element in it:
        result = function(result, element)
    return result

def zip_longest(*iterables):
    """Return an iterator that aggregates elements from each of the iterables. 
    Stop when the shortest input iterable is exhausted."""
    max_len = max(len(iterable) for iterable in iterables)
    it = iter(iterables)
    for i in range(max_len):
        try:
            yield [x[i] for x in it]
        except StopIteration:
            break

def chain(*iterables):
    """Return an iterator that returns elements from the first iterable until it is exhausted, 
    then proceeds to the next iterable, until all of the iterables are exhausted."""
    for it in iterables:
        yield from it

def compress_iter(iterable, predicate):
    """Return an iterator that filters elements from the iterable based on a predicate function."""
    return map_iter(iterable, lambda x: x if predicate(x) else None)

def cycle_iter(iterable):
    """Return an iterator that cycles over the elements of the iterable."""
    seen = set()
    while True:
        yield next((x for x in iterable if x not in seen), None)
        seen.add(x)

def repeat_iter(element, times):
    """Return an iterator that repeats the given element a specified number of times."""
    for _ in range(times):
        yield element
