import logging

class UtilityBelt:
    def __init__(self, headers=None, timeout=10):
        self.headers = headers if headers else {}
        self.timeout = timeout
        self.logger = logging.getLogger(__name__)

    def make_request(self, method, url, data=None, json_data=None):
        try:
            if method == 'json':
                response = requests.post(url, headers=self.headers, json=json_data, timeout=self.timeout)
            elif method == 'custom':
                response = requests.post(url, headers=self.headers, data=data, timeout=self.timeout)
            else:
                response = requests.get(url, headers=self.headers, timeout=self.timeout)
            response.raise_for_status()
            return response.json()
        except requests.exceptions.RequestException as e:
            self.logger.error(f"Request failed: {e}")
            return None

    def add_header(self, key, value):
        self.headers[key] = value

    def debug_request(self, method, url):
        print(f"Method: {method}, URL: {url}, Headers: {self.headers}")

def main():
    # Example usage
    utility_belt = UtilityBelt()
    utility_belt.add_header('Authorization', 'Bearer YOUR_TOKEN')
    response = utility_belt.make_request('json', 'https://api.example.com/endpoint', json_data={'key': 'value'})
    print(response)

if __name__ == "__main__":
