from typing import TypeVar, Generic, List, Tuple, Union

# Define a type variable for generics
T = TypeVar('T')

# Define a union type
class UnionType:
    def __init__(self, value):
        self.value = value

    def __repr__(self):
        return f"UnionType({self.value})"

# Define a tuple type
class TupleType:
    def __init__(self, elements):
        self.elements = elements

    def __repr__(self):
        return f"TupleType({self.elements})"

# Define a generic type
class GenericType(Generic[T]):
    def __init__(self, value: T):
        self.value = value

    def __repr__(self):
        return f"GenericType({self.value})"

# Define a function that uses union types
def union_type_example(value: UnionType):
    if isinstance(value, UnionType):
        print(f"UnionType: {value.value}")
    else:
        print("Not a UnionType")

# Define a function that uses tuple types
def tuple_type_example(value: TupleType):
    if isinstance(value, TupleType):
        print(f"TupleType: {value.elements}")
    else:
        print("Not a TupleType")

# Define a function that uses generic types
def generic_type_example<T>(value: GenericType[T]):
    print(f"GenericType: {value.value}")

# Test the functions
union_type_example(UnionType("Hello"))
union_type_example("World")  # This will not work with union types

tuple_type_example(TupleType([1, 2, 3]))
tuple_type_example(123)  # This will not work with tuple types

generic_type_example(GenericType("Hello"))
generic_type_example(GenericType(123))  # This will work with generic types
