import lxml.etree as etree

class XMLParser:
    def __init__(self, xml_string, max_depth=5):
        self.xml_string = xml_string
        self.max_depth = max_depth

    def parse_xml(self):
        try:
            root = etree.fromstring(self.xml_string)
            self._parse_tree(root, 0)
            return root
        except etree.XMLSyntaxError:
            raise
        except etree.XMLParserError as e:
            print(f"XML parser error: {e}")
            return None

    def _parse_tree(self, node, depth):
        if depth >= self.max_depth:
            raise ValueError("Excessive entity expansion detected")

        for child in node:
            self._parse_tree(child, depth + 1)

# Example usage:
xml_string = "<root><a><b><c/></b><d><e/></d></root>"
parser = XMLParser(xml_string)
root = parser.parse_xml()
```

