```python
import re

class Regex:
    def __init__(self, pattern):
        self.pattern = pattern
        self.groups = {}
        self.last_match = None

    def compile(self, pattern):
        self.pattern = re.escape(pattern)
        return self

    def match(self, string):
        match = re.match(self.pattern, string)
        if match:
            self.last_match = match
            for i, group in enumerate(match.groups()):
                self.groups[i] = group
        return match

    def search(self, string):
        match = re.search(self.pattern, string)
        if match:
            self.last_match = match
            for i, group in enumerate(match.groups()):
                self.groups[i] = group
        return match

    def findall(self, string):
        matches = re.findall(self.pattern, string)
        self.last_match = None
        return matches

    def finditer(self, string):
        return re.finditer(self.pattern, string)

    def fullmatch(self, string):
        match = re.fullmatch(self.pattern, string)
        if match:
            self.last_match = match
            for i, group in enumerate(match.groups()):
                self.groups[i] = group
        return match

    def partialmatch(self, string):
        match = re.partialmatch(self.pattern, string)
        if match:
            self.last_match = match
            for i, group in enumerate(match.groups()):
                self.groups[i] = group
        return match

    def split(self, string):
        matches = re.split(self.pattern, string)
        self.last_match = None
        return matches

    def sub(self, string, repl):
        return re.sub(self.pattern, repl, string)

    def subn(self, string, repl):
        return re.subn(self.pattern, repl, string)

    def subiter(self, string, repl):
        return re.subiter(self.pattern, repl, string)

    def replace(self, string, repl):
        return re.replace(self.pattern, repl, string)

    def escape(self, string):
        return re.escape(string)

    def verbose(self, string):
        return re.compile(self.pattern, re.VERBOSE | re.U)

    def debug(self, string):
        return re.compile(self.pattern, re.DOTALL | re.VERBOSE | re.U)

# Example usage:
regex = Regex(r'\d+')
print(regex.match('abc123def456').groups())  # {'1': '123', '2': '456'}
print(regex.search('abc123def456').groups())  # {'1': '123', '2': '456'}
print(regex.findall('abc123def456abc789def101'))  # ['123', '456', '789', '101']
print(regex.fullmatch('abc123def456').groups())  # {'1': '123', '2': '456'}
print(regex.search('abc123def456', 5, 10).groups())  # {'1': '123', '2': '456'}
```

