class StyleSheet:
    def __init__(self, name):
        self.name = name
        self.variables = {}
        self.styles = {}

    def add_variable(self, name, value):
        self.variables[name] = value

    def add_style(self, property_name, value):
        self.styles[property_name] = value

    def compose(self, other_stylesheet):
        composed_stylesheet = StyleSheet(self.name + "_composed")
        for property_name, value in self.variables.items():
            composed_stylesheet.add_variable(property_name, value)
        for property_name, value in other_stylesheet.variables.items():
            composed_stylesheet.add_variable(property_name, value)
        for property_name, value in self.styles.items():
            composed_stylesheet.add_style(property_name, value)
        for property_name, value in other_stylesheet.styles.items():
            composed_stylesheet.add_style(property_name, value)
        return composed_stylesheet

    def to_css(self):
        css = f"@{self.name} {{\n"
        for variable_name, value in self.variables.items():
            css += f"  --{variable_name}: {value};\n"
        for property_name, value in self.styles.items():
            css += f"  {property_name}: {value};\n"
        css += "}"
        return css


class Compositor:
    def __init__(self):
        self.stylesheets = []

    def add_stylesheet(self, stylesheet):
        self.stylesheets.append(stylesheet)

    def compose_stylesheets(self):
        composed_stylesheet = StyleSheet("composed")
        for stylesheet in self.stylesheets:
            composed_stylesheet = composed_stylesheet.compose(stylesheet)
        return composed_stylesheet

    def to_css(self):
        css = ""
        for stylesheet in self.stylesheets:
            css += stylesheet.to_css() + "\n"
        return css


# Example usage:
compositor = Compositor()
stylesheet1 = StyleSheet("stylesheet1")
stylesheet1.add_variable("primary-color", "#3498db")
stylesheet1.add_style("background-color", "#f9f9f9")
stylesheet1.add_style("color", "#333333")

stylesheet2 = StyleSheet("stylesheet2")
stylesheet2.add_variable("primary-color", "#2ecc71")
stylesheet2.add_style("background-color", "#f1c40f")
stylesheet2.add_style("color", "#2ecc71")

compositor.add_stylesheet(stylesheet1)
compositor.add_stylesheet(stylesheet2)

composed_stylesheet = compositor.compose_stylesheets()
print(composed_stylesheet.to_css())
```

