        self.config_file = config_file
        self.config = self.load_config()

    def load_config(self):
        if os.path.exists(self.config_file):
            with open(self.config_file, 'r') as f:
                return json.load(f)
        else:
            return {}

    def save_config(self):
        with open(self.config_file, 'w') as f:
            json.dump(self.config, f, indent=4)

class Dependencies:
    def __init__(self, config):
        self.config = config
        self.dependencies = self.config.get('dependencies', [])

    def install_dependencies(self):
        for dependency in self.dependencies:
            print(f"Installing {dependency['name']}")

class App:
    def __init__(self, config):
        self.config = config
        self.settings = self.config.get('settings', {})

    def run(self):
        if 'server' in self.settings:
            print(f"Running server on {self.settings['server']['port']}")
        elif 'cli' in self.settings:
            print(f"Running CLI on {self.settings['cli']['port']}")
        else:
            print("No server or CLI specified")

def main():
