```python
import mmap
import os
import sys

class SlidingWindowMemoryMap:
    def __init__(self, size):
        self.size = size
        self.window = None
        self.memory_map = {}

    def create_memory_map(self):
        if not self.window:
            self.window = mmap.mmap(-1, self.size, access=mmap.ACCESS_READ)
            for i in range(self.size):
                self.memory_map[i] = i

    def allocate(self, address):
        if address not in self.memory_map:
            self.create_memory_map()
            self.memory_map[address] = address
            return address
        else:
            return self.memory_map[address]

    def deallocate(self, address):
        if address in self.memory_map:
            del self.memory_map[address]

    def resize(self, new_size):
        if self.size < new_size:
            self.window.close()
            self.window = mmap.mmap(-1, new_size, access=mmap.ACCESS_READ)
            self.memory_map = {}
            for i in range(new_size):
                self.memory_map[i] = i
        elif self.size > new_size:
            self.window.close()
            self.window = mmap.mmap(-1, new_size, access=mmap.ACCESS_READ)
            self.memory_map = {}
            for i in range(new_size):
                self.memory_map[i] = i

# Example usage
swmm = SlidingWindowMemoryMap(1024)
swmm.allocate(512)
print(swmm.memory_map[512])
swmm.deallocate(512)
swmm.resize(2048)
