import importlib
import inspect
import sys

def sort_imports():
    sorted_imports = {}
    for filename in sys.modules.values():
        module = importlib.import_module(filename.name)
        for name in dir(module):
            obj = getattr(module, name)
            if inspect.ismodule(obj):
                if obj not in sorted_imports:
                    sorted_imports[obj] = []
                sorted_imports[obj].append((name, inspect.getfile(obj)))

    sorted_imports = dict(sorted(sorted_imports.items(), key=lambda item: (len(item[1]), item[1][0])))
    for module, imports in sorted_imports.items():
        print(f"Module: {module}")
        for line, filename in imports:
            print(f"  Line {line}: {filename}")

sort_imports()
