import re
from functools import lru_cache

class Template:
    def __init__(self, template_str):
        self.template_str = template_str
        self.tokens = self.tokenize()
        self.cache = {}
        self.cache = self._cache_tokens()

    def tokenize(self):
        tokens = re.findall(r'{{(.*?)}}', self.template_str)
        return tokens

    def _cache_tokens(self):
        @lru_cache(maxsize=None)
        def cached_tokenization():
            return self.tokenize()
        return cached_tokenization()

    def render(self, **kwargs):
        for token in self.tokens:
            if token in kwargs:
                self.template_str = self.template_str.replace('{{' + token + '}}', str(kwargs[token]))
        return self.template_str

# Example usage:
template = Template('Hello {{name}}, your age is {{age}}')
print(template.render(name='John', age=30))
