```python
import threading
import time
import uuid
import pickle
import os

class TinyShelve:
    def __init__(self, db_path):
        self.db_path = db_path
        self.lock = threading.Lock()
        self.db = {}
        self.init_db()

    def init_db(self):
        if not os.path.exists(self.db_path):
            with open(self.db_path, 'wb') as f:
                pickle.dump({}, f)

    def get(self, key):
        with self.lock:
            return self.db.get(key)

    def put(self, key, value):
        with self.lock:
            self.db[key] = value

    def delete(self, key):
        with self.lock:
            if key in self.db:
                del self.db[key]

    def clear(self):
        with self.lock:
            self.db.clear()

    def __contains__(self, key):
        with self.lock:
            return key in self.db

    def __len__(self):
        with self.lock:
            return len(self.db)

    def __getitem__(self, key):
        with self.lock:
            return self.db[key]

    def __setitem__(self, key, value):
        with self.lock:
            self.db[key] = value

    def __delitem__(self, key):
        with self.lock:
            if key in self.db:
                del self.db[key]

# Example usage:
db = TinyShelve('tiny_shelve.db')
db['key1'] = 'value1'
print(db['key1'])  # Output: value1

def worker(key, value):
