import gettext
import locale
from datetime import datetime
from decimal import Decimal

class Internationalization:
    def __init__(self, language='en_US', locale_name=None):
        self.language = language
        self.locale_name = locale_name

    def set_language(self, language):
        self.language = language

    def set_locale(self, locale_name):
        self.locale_name = locale_name

    def translate_message(self, message, domain='messages'):
        if not hasattr(self, 'gettext'):
            self.gettext = gettext.translation(domain, localedir='locale', languages=[self.language])
        return self.gettext.ugettext(message)

    def get_date_time_formatter(self, date_time):
        return self.translate_message(f"DATE_TIME_FORMATTER_{date_time.strftime('%Y-%m-%d %H:%M:%S')}")

    def get_number_formatter(self, number):
        return self.translate_message(f"NUMBER_FORMATTER_{number}")

    def get_currency_formatter(self, currency):
        return self.translate_message(f"CURRENCY_FORMATTER_{currency}")

    def set_default_locale(self):
        locale.setlocale(locale.LC_ALL, self.locale_name)

# Example usage
if __name__ == "__main__":
    i18n = Internationalization()
    i18n.set_locale('de_DE')
    i18n.set_default_locale()

    print(i18n.translate_message('Hello, World!'))
    print(i18n.get_date_time_formatter(datetime.now()))
    print(i18n.get_number_formatter(12345))
    print(i18n.get_currency_formatter('USD'))
