```python
import ast
import re
import sys

def check_vulnerabilities(code):
    # Initialize a dictionary to store the results
    results = {
        'vulnerabilities': [],
        'best_practices': []
    }

    # Parse the abstract syntax tree
    tree = ast.parse(code)

    # Check for SQL injection vulnerability
    for node in ast.walk(tree):
        if isinstance(node, ast.Str):
            if re.search(r'\bSELECT\b|\bINSERT\b|\bUPDATE\b|\bDELETE\b', node.s, re.IGNORECASE):
                results['vulnerabilities'].append(f"Potential SQL injection vulnerability: {node.s}")

    # Check for sensitive data exposure
    for node in ast.walk(tree):
        if isinstance(node, ast.Str):
            if re.search(r'\bpassword\b|\bapi_key\b|\bsecret_key\b', node.s, re.IGNORECASE):
                results['vulnerabilities'].append(f"Potential sensitive data exposure: {node.s}")

    # Check for insecure password storage
    for node in ast.walk(tree):
        if isinstance(node, ast.Str):
            if re.search(r'\bbcrypt\b|\bargon2\b|\bpbkdf2\b', node.s, re.IGNORECASE):
                # Check if the password is being stored directly
                if isinstance(node.parent, (ast.Assign, ast.Store)):
                    results['best_practices'].append(f"Insecure password storage: {node.s}")

    # Check for weak passwords
    for node in ast.walk(tree):
        if isinstance(node, ast.Str):
            if re.search(r'\b12345\b|\babcde\b|\babc123\b', node.s, re.IGNORECASE):
                results['best_practices'].append(f"Weak password: {node.s}")

    # Check for insecure HTTP headers
    for node in ast.walk(tree):
        if isinstance(node, ast.Str):
            if re.search(r'\bXSS\b|\bXSRF\b', node.s, re.IGNORECASE):
                results['best_practices'].append(f"Insecure HTTP header: {node.s}")

    return results

def main():
    if len(sys.argv) != 2:
        print("Usage: python script.py <python_code>")
        return

    code = open(sys.argv[1], 'r').read()
    results = check_vulnerabilities(code)

    if results['vulnerabilities']:
        print("Vulnerabilities:")
        for vulnerability in results['vulnerabilities']:
            print(vulnerability)
    else:
        print("No vulnerabilities found.")

    if results['best_practices']:
        print("\nBest Practices:")
        for best_practice in results['best_practices']:
            print(best_practice)

if __name__ == "__main__":
    main()
```

