import dns.resolver
import dns.update
import dns.zone

class DNSClient:
    def __init__(self, dns_server):
        self.dns_server = dns_server

    def query_dns_record(self, domain, record_type):
        try:
            answers = dns.resolver.resolve(domain, record_type)
            return [answer.to_text() for answer in answers]
        except dns.resolver.NoAnswer:
            return []
        except dns.resolver.NXDOMAIN:
            return []

    def modify_dns_record(self, domain, record_type, new_value):
        try:
            zone = dns.zone.from_xfr(self.dns_server)
            update = dns.update.Update(zone, allow_overwrite=True)
            update.add(domain, record_type, new_value)
            update.send(dns.rdtc.zone)
            return True
        except dns.update.Error:
            return False

    def test_dns_server_connectivity(self):
        try:
            dns.resolver.resolve('8.8.8.8', 'A')
            return True
        except dns.resolver.NoAnswer:
            return False

# Example usage
if __name__ == "__main__":
    dns_client = DNSClient('1.1.1.1')  # Replace with your DNS server
    print(dns_client.query_dns_record('example.com', 'A'))
    dns_client.modify_dns_record('example.com', 'A', '192.0.2.1')
    print(dns_client.test_dns_server_connectivity())
