import types

class AttributeTracker(types.SimpleProxyType):
    def __init__(self, obj):
        super().__init__(obj)
        self.access_count = {}

    def __getattr__(self, name):
        if name not in self.access_count:
            self.access_count[name] = 0
        self.access_count[name] += 1
        return super().__getattr__(name)

# Example usage:
class TestObject:
    def __init__(self, value):
        self.value = value

    def get_value(self):
        return self.value

tracker = AttributeTracker(TestObject(10))
print(tracker.get_value())  # Output: 10
print(tracker.value)  # Output: 10
print(tracker.access_count)  # Output: {'value': 2}
