import ipaddress
import dns.resolver

def ip_conversion(ip):
    try:
        # Convert IPv4 to IPv6
        ipv4 = ipaddress.IPv4Address(ip)
        ipv6 = ipaddress.IPv6Address(str(ipv4))
        return str(ipv6), "IPv4 to IPv6"
    except ValueError:
        try:
            # Convert IPv6 to IPv4
            ipv6 = ipaddress.IPv6Address(ip)
            ipv4 = ipaddress.IPv4Address(str(ipv6))
            return str(ipv4), "IPv6 to IPv4"
        except ValueError:
            return None, None

def dns_lookup(domain):
    try:
        # Perform DNS lookup
        answers = dns.resolver.resolve(domain, 'A')
        return [str(answer) for answer in answers]
    except dns.resolver.NoAnswer:
        return None
    except dns.resolver.NXDOMAIN:
        return None

def subnet_mask(ip):
    try:
        # Calculate subnet mask
        network = ipaddress.ip_network(ip, strict=False)
        return str(network.netmask)
    except ValueError:
        return None

# Example usage
print(ip_conversion("192.168.1.1"))
print(dns_lookup("www.google.com"))
print(subnet_mask("192.168.1.0/24"))
```

