import functools

def deprecated(message, replacement):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            print(f"{message} This function is deprecated and should not be used.")
            return replacement(*args, **kwargs)
        wrapper.__doc__ = func.__doc__.replace("def", f"@deprecated('{message}') def")
        return wrapper
    return decorator
