from elasticsearch import Elasticsearch, ElasticsearchException

# Initialize Elasticsearch client
es = Elasticsearch([{'host': 'localhost', 'port': 9200}])

# Create index
def create_index(index_name):
    try:
        es.indices.create(index=index_name)
        print(f"Index {index_name} created successfully.")
    except ElasticsearchException as e:
        print(f"Error creating index {index_name}: {e}")

# Delete index
def delete_index(index_name):
    try:
        es.indices.delete(index=index_name)
        print(f"Index {index_name} deleted successfully.")
    except ElasticsearchException as e:
        print(f"Error deleting index {index_name}: {e}")

# Index document
def index_document(index_name, doc_id, data):
    try:
        es.index(index=index_name, id=doc_id, body=data)
        print(f"Document with id {doc_id} indexed successfully.")
    except ElasticsearchException as e:
        print(f"Error indexing document with id {doc_id}: {e}")

# Update document
def update_document(index_name, doc_id, data):
    try:
        es.update(index=index_name, id=doc_id, body=data)
        print(f"Document with id {doc_id} updated successfully.")
    except ElasticsearchException as e:
        print(f"Error updating document with id {doc_id}: {e}")

# Delete document
def delete_document(index_name, doc_id):
    try:
        es.delete(index=index_name, id=doc_id)
        print(f"Document with id {doc_id} deleted successfully.")
    except ElasticsearchException as e:
        print(f"Error deleting document with id {doc_id}: {e}")

# Search for documents
def search_documents(index_name, query):
    try:
        response = es.search(index=index_name, body=query)
        return response['hits']['hits']
    except ElasticsearchException as e:
        print(f"Error searching documents: {e}")
        return []

# Example usage
if __name__ == "__main__":
    # Create index
    create_index("my_index")

    # Index document
    index_document("my_index", "1", {"name": "John", "age": 30})

    # Update document
    update_document("my_index", "1", {"name": "Jane", "age": 31})

    # Search for documents
    query = {"query": {"match": {"name": "John"}}}
    results = search_documents("my_index", query)
    for result in results:
        print(result["_source"])

    # Delete document
    delete_document("my_index", "1")

    # Delete index
    delete_index("my_index")
