```python
import socket
import struct

class HTTPResponse:
    def __init__(self, status_code, reason, headers, body):
        self.status_code = status_code
        self.reason = reason
        self.headers = headers
        self.body = body

class HTTPRequest:
    def __init__(self, method, url, headers, body):
        self.method = method
        self.url = url
        self.headers = headers
        self.body = body

class HTTPServer:
    def __init__(self, host, port):
        self.host = host
        self.port = port
        self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server_socket.bind((self.host, self.port))
        self.server_socket.listen(5)

    def handle_request(self, client_socket):
        request = self.parse_request(client_socket)
        response = self.handle_request_handler(request)
        self.send_response(client_socket, response)

    def parse_request(self, client_socket):
        request_line, headers, body = self.parse_request_line(client_socket)
        return HTTPRequest(request_line.method, request_line.url, headers, body)

    def parse_request_line(self, client_socket):
        request_line = self.read_line(client_socket)
        headers = {}
        body = ''
        while True:
            header = self.read_line(client_socket)
            if not header:
                break
            key, value = self.parse_header(header)
            headers[key] = value
            if header.endswith('\r\n'):
                break
        body = self.read_line(client_socket)
        return HTTPRequest(request_line, headers, body)

    def parse_header(self, line):
        key, value = line.split(':', 1)
        return key.strip(), value.strip()

    def read_line(self, client_socket):
        line = ''
        while True:
            chunk = client_socket.recv(1024)
            if not chunk:
                break
            line += chunk.decode('utf-8')
            if '\r\n' in line:
                break
        return line

    def handle_request_handler(self, request):
        if request.method == 'GET':
            return self.get_handler(request)
        elif request.method == 'POST':
            return self.post_handler(request)
        else:
            return HTTPResponse(405, 'Method Not Allowed', {}, 'Method Not Allowed')

    def get_handler(self, request):
        return HTTPResponse(200, 'OK', {'Content-Type': 'text/plain'}, 'Hello, World!')

    def post_handler(self, request):
        return HTTPResponse(201, 'Created', {'Content-Type': 'text/plain'}, 'Hello, World!')

    def send_response(self, client_socket, response):
        response_body = ''
        for header in response.headers:
            response_body += f'{header}: {response.headers[header]}\r\n'
        response_body += '\r\n'
        response_body += response.body
        client_socket.sendall((f'HTTP/1.1 {response.status_code} {response.reason}\r\n').encode('utf-8'))
        client_socket.sendall(response_body.encode('utf-8'))

    def start(self):
        print(f'Server started on {self.host}:{self.port}')
        while True:
            client_socket, address = self.server_socket.accept()
            self.handle_request(client_socket)

server = HTTPServer('127.0.0.1', 8000)
server.start()
```

