def cache_property(func):
    cache = {}

    def wrapper(self, *args, **kwargs):
        key = (self.__class__.__name__, func.__name__, args, frozenset(kwargs.items()))
        if key in cache:
            return cache[key]
        result = func(self, *args, **kwargs)
        cache[key] = result
        return result

    wrapper.__dict__.update(func.__dict__)
    return wrapper
