import contextlib
from typing import Optional, Any

def contextmanager(cls: type) -> type:
    """A decorator to make a class a context manager."""
    return contextlib.contextmanager(cls)

@contextmanager
def my_context_manager():
    """A simple context manager."""
    print("Entering the context.")
    try:
        yield
    finally:
        print("Exiting the context.")

# Usage
with my_context_manager() as manager:
    print("Inside the context.")

# Enhanced context manager with improved function annotation
@contextmanager
def enhanced_context_manager() -> None:
    """A context manager with improved function annotation."""
    print("Entering the context.")
    try:
        yield
    finally:
        print("Exiting the context.")

# Usage
with enhanced_context_manager() -> None:
    print("Inside the context.")

# Backporting contextlib.suppress for Python 3.3 and earlier
if hasattr(contextlib, 'suppress'):
    from contextlib import suppress
else:
    from contextlib import contextmanager

    @contextmanager
    def suppress(*exceptions):
        """A context manager to suppress exceptions."""
        try:
            yield
        except Exception as e:
            if any(isinstance(e, exc_type) for exc_type in exceptions):
                raise
            else:
                return

    suppress = suppress
