```python
import struct
import typing

class DataTypeConverter:
    @staticmethod
    def convert_to_native(data: typing.Any, data_type: str) -> typing.Any:
        """
        Converts complex data type to native Python data type.

        Args:
        data (typing.Any): The complex data to be converted.
        data_type (str): The type of data the input data represents.

        Returns:
        typing.Any: The converted native Python data type.
        """
        if data_type == 'int':
            return int(data)
        elif data_type == 'float':
            return float(data)
        elif data_type == 'bool':
            return bool(data)
        elif data_type == 'str':
            return str(data)
        elif data_type == 'tuple':
            return tuple(DataTypeConverter.convert_to_native(item, 'int') for item in data)
        elif data_type == 'list':
            return [DataTypeConverter.convert_to_native(item, 'int') for item in data]
        elif data_type == 'dict':
            return {DataTypeConverter.convert_to_native(key, 'str'): DataTypeConverter.convert_to_native(value, 'int') for key, value in data.items()}
        elif data_type == 'bytes':
            return bytes(data)
        else:
            raise ValueError(f"Unsupported data type: {data_type}")

    @staticmethod
    def convert_from_native(data: typing.Any, data_type: str) -> typing.Any:
        """
        Converts native Python data type to complex data type.

        Args:
        data (typing.Any): The native Python data to be converted.
        data_type (str): The type of data the input data represents.

        Returns:
        typing.Any: The converted complex data type.
        """
        if data_type == 'int':
            return int(data)
        elif data_type == 'float':
            return float(data)
        elif data_type == 'bool':
            return bool(data)
        elif data_type == 'str':
            return str(data)
        elif data_type == 'tuple':
            return tuple(DataTypeConverter.convert_from_native(item, 'int') for item in data)
        elif data_type == 'list':
            return [DataTypeConverter.convert_from_native(item, 'int') for item in data]
        elif data_type == 'dict':
            return {DataTypeConverter.convert_from_native(key, 'str'): DataTypeConverter.convert_from_native(value, 'int') for key, value in data.items()}
        elif data_type == 'bytes':
            return bytes(data)
        else:
            raise ValueError(f"Unsupported data type: {data_type}")

    @staticmethod
    def convert(data: typing.Any, data_type: str) -> typing.Any:
        """
        Converts complex data type to and from native Python data type.

        Args:
        data (typing.Any): The complex data to be converted.
        data_type (str): The type of data the input data represents.

        Returns:
        typing.Any: The converted native Python data type.
        """
        if isinstance(data, (int, float, bool, str, bytes, tuple, list, dict)):
            return data
        elif isinstance(data, typing.Union):
            return typing.cast(typing.Any, DataTypeConverter.convert_from_native(data, data_type))
        elif isinstance(data, typing.Union):
            return typing.cast(typing.Any, DataTypeConverter.convert_to_native(data, data_type))
        else:
            raise ValueError(f"Unsupported data type: {type(data)}")

# Example usage:
complex_data = {'name': 'John', 'age': 30, 'city': 'New York', 'scores': [90, 85, 95], 'is_admin': True}
native_data = DataTypeConverter.convert(complex_data, 'int')
print(native_data)  # Output: [0, 85, 95, 0]

converted_data = DataTypeConverter.convert(native_data, 'dict')
print(converted_data)  # Output: {'name': 0, 'age': 85, 'city': 95, 'scores': 0, 'is_admin': True}
```

