import tornado.web
import tornado.websocket
import json

class TerminalHandler(tornado.websocket.WebSocketHandler):
    def open(self):
        self.write_message(json.dumps({'message': 'connected'}))

    def on_message(self, message):
        try:
            command = json.loads(message)['command']
            if command == 'exit':
                self.close()
            else:
                # Simulate terminal output
                output = f'User input: {command}\n'
                self.write_message(json.dumps({'output': output}))
        except (json.JSONDecodeError, KeyError):
            self.write_message(json.dumps({'error': 'Invalid JSON message'}))

    def on_close(self):
        self.write_message(json.dumps({'message': 'disconnected'}))

class TerminalApplication(tornado.web.Application):
    def __init__(self):
        handlers = [
            (r'/terminal', TerminalHandler),
        ]
        super(TerminalApplication, self).__init__(handlers)

if __name__ == '__main__':
    application = TerminalApplication()
    application.listen(8888)
    tornado.ioloop.IOLoop.current().start()
