```python
import multiprocessing
import signal
import time

class ThreadPool:
    def __init__(self, num_workers):
        self.num_workers = num_workers
        self.pool = multiprocessing.Pool(num_workers)
        self.stopped = multiprocessing.Value('b', False)

    def start(self):
        self.stopped.clear()
        self.pool.apply_async(self._start_workers)

    def stop(self):
        self.stopped.set(True)
        self.pool.close()
        self.pool.join()

    def _start_workers(self):
        while not self.stopped.value:
            try:
                func = self.pool._worker_init()
                self.pool.apply_async(func)
            except Exception as e:
                print(f"Error in worker: {e}")

    def submit(self, func, *args, **kwargs):
        return self.pool.apply_async(func, args, kwargs)

    def shutdown(self):
        self.stop()

    def terminate(self):
        self.stop()
        self.pool.join()


def main():
    # Usage example
    pool = ThreadPool(5)
    pool.start()

    def example_func(x):
        time.sleep(x)
        print(f"Finished {x}")

    pool.submit(example_func, 2).get()
    pool.submit(example_func, 1).get()
    pool.submit(example_func, 3).get()

    pool.shutdown()


if __name__ == "__main__":
    main()
```

