# Test file existence
def test_file_existence(file_path):
    if os.path.exists(file_path):
        print(f"File {file_path} exists.")
    else:
        print(f"File {file_path} does not exist.")

# Test file content
def test_file_content(file_path):
    try:
        with open(file_path, 'r') as file:
            content = file.read()
            print(f"Content of {file_path}: {content}")
    except FileNotFoundError:
        print(f"File {file_path} does not exist.")
    except Exception as e:
        print(f"An error occurred: {e}")

# Test directory existence
def test_directory_existence(directory_path):
    if os.path.exists(directory_path) and os.path.isdir(directory_path):
        print(f"Directory {directory_path} exists.")
    else:
        print(f"Directory {directory_path} does not exist.")

# Execute a command
def execute_command(command):
    try:
        output = os.popen(command).read()
        print(f"Command output: {output}")
    except Exception as e:
        print(f"An error occurred: {e}")

# Test environment variable
def test_environment_variable(var_name):
    if var_name in os.environ:
        print(f"Environment variable {var_name} is set to {os.environ[var_name]}")
    else:
        print(f"Environment variable {var_name} is not set.")

# Example usage
if __name__ == "__main__":
    test_file_existence("test.txt")
    test_file_content("test.txt")
    test_directory_existence("/path/to/directory")
    execute_command("ls -l")
    test_environment_variable("PATH")
