import packaging

def get_package_metadata(package_name):
    try:
        package = packaging.require(package_name)
        metadata = {
            "version": package.version,
            "license": package.license,
            "author": package.author,
            "description": package.description,
        }
        return metadata
    except packaging.exceptions.DistributionNotFound:
        return None

def get_installed_package_metadata():
    import pkg_resources
    metadata = {}
    for dist in pkg_resources.working_set:
        metadata[dist.project_name] = {
            "version": dist.version,
            "license": dist.author,
            "description": dist.description,
        }
    return metadata

# Example usage
package_name = "numpy"
print(get_package_metadata(package_name))

installed_packages = get_installed_package_metadata()
for package, metadata in installed_packages.items():
    print(f"Package: {package}")
    print(f"Version: {metadata['version']}")
    print(f"License: {metadata['license']}")
    print(f"Author: {metadata['author']}")
    print(f"Description: {metadata['description']}")
    print("-" * 50)
