```python
import functools
import operator

def convert_list_format(input_list, output_format):
    if output_format == 'tuple':
        return tuple(input_list)
    elif output_format == 'set':
        return set(input_list)
    elif output_format == 'dict':
        return {k: v for k, v in input_list}
    else:
        raise ValueError('Invalid output format')

def insert_element_at_index(input_list, index, element):
    return input_list[:index] + [element] + input_list[index:]

def insert_element_at_end(input_list, element):
    return input_list + [element]

def insert_element_at_start(input_list, element):
    return [element] + input_list

def remove_element(input_list, element):
    return [x for x in input_list if x != element]

def replace_element(input_list, old_element, new_element):
    return [new_element if x == old_element else x for x in input_list]

def search_element(input_list, element):
    try:
        return input_list.index(element)
    except ValueError:
        return -1

def sort_list(input_list):
    return sorted(input_list)

def sort_list_reverse(input_list):
    return sorted(input_list, reverse=True)

def filter_list(input_list, predicate):
    return [x for x in input_list if predicate(x)]

def map_list(input_list, function):
    return [function(x) for x in input_list]

def reduce_list(input_list, function):
    return functools.reduce(function, input_list, None)

def group_by(input_list, key):
    return {key(x): [x for x in input_list if key(x) == key] for x in input_list}

def get_first_element(input_list):
    return input_list[0] if input_list else None

def get_last_element(input_list):
    return input_list[-1] if input_list else None

def get_max_element(input_list):
    return max(input_list) if input_list else None

def get_min_element(input_list):
    return min(input_list) if input_list else None

def get_sum(input_list):
    return sum(input_list) if input_list else None

def get_average(input_list):
    return sum(input_list) / len(input_list) if input_list else None
