import json

def serialize_object(obj, indent=0):
    """Recursively serialize an object into a JSON string."""
    if isinstance(obj, dict):
        return '{' + ', '.join(f'"{key}": {serialize_object(value, indent + 2)}' for key, value in obj.items()) + '}'
    elif isinstance(obj, list):
        return '[' + ', '.join(serialize_object(item, indent + 2) for item in obj) + ']'
    elif hasattr(obj, '__dict__'):
        return '{' + ', '.join(f'"{key}": {serialize_object(value, indent + 2)}' for key, value in obj.__dict__.items()) + '}'
    else:
        return str(obj)

# Example usage:
obj = {
    'name': 'John',
    'age': 30,
    'interests': ['reading', 'hiking', 'coding'],
    'address': {
        'street': '123 Main St',
        'city': 'Anytown',
        'state': 'CA',
        'zip': '12345'
    }
}

json_string = json.dumps(serialize_object(obj), indent=4)
print(json_string)
