import ast
import astunparse
import astroid

class RefactorAST(astroid.NodeTransformer):
    def __init__(self, source_code):
        self.source_code = source_code
        self.ast = ast.parse(source_code)
        self.astroid_ast = astroid.from_source(source_code)

    def rename_variables(self, node):
        for child in ast.iter_child_nodes(node):
            if isinstance(child, ast.Name):
                child.id = child.id + '_temp'
        return node

    def move_definitions(self, node):
        for child in ast.iter_child_nodes(node):
            if isinstance(child, ast.Assign):
                for target in child.targets:
                    if isinstance(target, ast.Name):
                        target.id = target.id + '_temp'
        return node

    def consolidate_similar_code(self, node):
        if isinstance(node, ast.If):
            for child in ast.iter_child_nodes(node):
                if isinstance(child, ast.With):
                    for target in child.items:
                        if isinstance(target.value, ast.Name):
                            target.value.id = target.value.id + '_temp'
        return node

    def refactor_ast(self):
        # Refactor the AST using the defined techniques
        self.ast = self.rename_variables(self.ast)
        self.astroid_ast = self.move_definitions(self.astroid_ast)
        self.ast = self.consolidate_similar_code(self.ast)
        self.astroid_ast = self.consolidate_similar_code(self.astroid_ast)

        # Convert the refactored AST back to source code
        refactored_source_code = astunparse.unparse(self.astroid_ast)

        return refactored_source_code

# Example usage:
source_code = """
x = 5
y = 10
if x > y:
    print('x is greater than y')
else:
    print('y is greater than x')
"""

refactor_ast = RefactorAST(source_code)
refactored_source_code = refactor_ast.refactor_ast()
print(refactored_source_code)
```

