import os
from google.cloud import storage

class GoogleCloudStorage:
    def __init__(self, bucket_name):
        self.bucket_name = bucket_name
        self.client = storage.Client()
        self.bucket = self.client.get_bucket(bucket_name)

    def list_buckets(self):
        return self.bucket.list_blobs()

    def list_objects(self, prefix=''):
        return self.bucket.list_blobs(prefix=prefix)

    def upload_file(self, local_file_path, object_name):
        blob = self.bucket.blob(object_name)
        blob.upload_from_filename(local_file_path)

    def download_file(self, object_name, local_file_path):
        blob = self.bucket.blob(object_name)
        blob.download_to_filename(local_file_path)

    def mkdir(self, directory):
        blob = self.bucket.blob(directory)
        blob.create()

    def rmdir(self, directory):
        blob = self.bucket.blob(directory)
        blob.delete()

    def remove_file(self, object_name):
        blob = self.bucket.blob(object_name)
        blob.delete()

    def get_file_size(self, object_name):
        blob = self.bucket.blob(object_name)
        return blob.size

    def is_directory(self, object_name):
        return self.get_file_size(object_name) != 0

# Example usage:
if __name__ == "__main__":
    gcs = GoogleCloudStorage("your-bucket-name")
    gcs.upload_file("local_file_path", "object_name")
    gcs.download_file("object_name", "local_file_path")
    gcs.mkdir("directory")
    gcs.rmdir("directory")
    gcs.remove_file("object_name")
    print(gcs.get_file_size("object_name"))
    print(gcs.is_directory("object_name"))
