import requests
from io import BytesIO
from typing import Any

class FileTransportAdapter:
    def __init__(self, url: str):
        self.url = url

    def get(self, params: Any = None) -> requests.Response:
        response = requests.get(self.url, params=params)
        return response

    def post(self, data: Any = None, json: Any = None) -> requests.Response:
        response = requests.post(self.url, data=data, json=json)
        return response

    def put(self, data: Any = None, json: Any = None) -> requests.Response:
        response = requests.put(self.url, data=data, json=json)
        return response

    def delete(self) -> requests.Response:
        response = requests.delete(self.url)
        return response

    def send_file(self, filename: str, chunk_size: int = 1024) -> requests.Response:
        with open(filename, 'rb') as file:
            response = requests.put(self.url, data=file, stream=True, chunk_size=chunk_size)
            return response

    def receive_file(self, filename: str, chunk_size: int = 1024) -> None:
        with open(filename, 'wb') as file:
            for chunk in self.get().iter_content(chunk_size=chunk_size):
                file.write(chunk)
