import sys
import functools

def singledispatch(type_):
    def decorator(func):
        dispatch_table = {}
        def wrapper(*args, **kwargs):
            key = args[0]
            if key not in dispatch_table:
                raise TypeError(f"no such type: {type_.__name__}")
            return dispatch_table[key](func, *args[1:], **kwargs)
        wrapper.dispatch_table = dispatch_table
        return wrapper
    def dispatch(self, key, func):
        if key not in self.dispatch_table:
            raise TypeError(f"no such type: {type_.__name__}")
        return self.dispatch_table[key](func)
    return decorator, dispatch

if sys.version_info < (3, 5):
    from functools import singledispatch as _singledispatch
    from functools import wraps

    def len_(func):
        @singledispatch
        def _len_(self, key):
            return 0
        return _len_

    len = len_
else:
    len = None
