import json

def extract_nodes(json_doc, node_key):
    try:
        # Parse the JSON document
        data = json.loads(json_doc)

        # Define a recursive function to extract nodes
        def extract(data):
            if isinstance(data, dict):
                if node_key in data:
                    yield data[node_key]
                for value in data.values():
                    yield from extract(value)
            elif isinstance(data, list):
                for item in data:
                    yield from extract(item)

        # Extract nodes from the JSON document
        nodes = extract(data)

        return nodes

    except json.JSONDecodeError as e:
        print(f"Error parsing JSON: {e}")
        return None

# Example usage
json_doc = '{"name": "John", "age": 30, "city": "New York"}'
node_key = 'city'
nodes = extract_nodes(json_doc, node_key)
print(nodes)  # Output: ['New York']
```

