from dateutil import parser
from datetime import datetime
import pytz

def parse_date_time(date_time_str):
    try:
        date_time_obj = parser.parse(date_time_str)
        return date_time_obj
    except ValueError:
        return None

def compare_date_times(date_time_obj1, date_time_obj2):
    if date_time_obj1.tzinfo != date_time_obj2.tzinfo:
        date_time_obj1 = date_time_obj1.astimezone(date_time_obj2.tzinfo)
    return date_time_obj1 - date_time_obj2

def format_date_time(date_time_obj):
    return date_time_obj.strftime("%Y-%m-%d %H:%M:%S")

def format_duration(duration):
    hours, remainder = divmod(duration.total_seconds(), 3600)
    minutes, seconds = divmod(remainder, 60)
    return f"{int(hours)} hours, {int(minutes)} minutes, {int(seconds)} seconds"

def compare_date_time_strings(date_time_str1, date_time_str2):
    date_time_obj1 = parse_date_time(date_time_str1)
    date_time_obj2 = parse_date_time(date_time_str2)

    if date_time_obj1 is None or date_time_obj2 is None:
        return "Invalid date time string"

    duration = compare_date_times(date_time_obj1, date_time_obj2)
    if duration < 0:
        return "date_time_str1 is earlier than date_time_str2"
    elif duration > 0:
        return f"date_time_str1 is {duration} seconds later than date_time_str2"
    else:
        return "date_time_str1 and date_time_str2 are the same"

def format_date_time_string(date_time_str, format_str):
    date_time_obj = parse_date_time(date_time_str)
    if date_time_obj is not None:
        return format_date_time(date_time_obj).replace("%Y-%m-%d", format_str)
    else:
        return "Invalid date time string"

# Test the functions
date_time_str1 = "2015-06-11 10:00:00"
date_time_str2 = "in 3 hours"
date_time_str3 = "2015-06-12 10:00:00"

print(compare_date_time_strings(date_time_str1, date_time_str2))
print(compare_date_time_strings(date_time_str1, date_time_str3))
print(format_date_time_string(date_time_str1, "%Y-%m-%d"))
print(format_date_time_string(date_time_str2, "%H:%M:%S"))
```

