import datetime
import pytz
import time

# Mapping of time zone names to their respective offsets
TIMEZONE_MAP = {
    'America/New_York': pytz.timezone('America/New_York'),
    'America/Los_Angeles': pytz.timezone('America/Los_Angeles'),
    'Europe/London': pytz.timezone('Europe/London'),
    # Add more time zones as needed
}

def get_timezone(name):
    return TIMEZONE_MAP.get(name)

def get_timezone_offset(tz):
    return tz.utcoffset(datetime.datetime.now(tz))

def to_timezone(date, timezone_name):
    tz = get_timezone(timezone_name)
    return date.astimezone(tz)

def from_timezone(date, timezone_name):
    tz = get_timezone(timezone_name)
    return date.replace(tzinfo=tz)

def timezone_aware(date, timezone_name):
    tz = get_timezone(timezone_name)
    return datetime.datetime.now(tz)

def timezone_aware_from(date, timezone_name):
    tz = get_timezone(timezone_name)
    return date.astimezone(tz)

def timezone_aware_to(date, timezone_name):
    tz = get_timezone(timezone_name)
    return date.replace(tzinfo=tz)
