```python
import socket
import select
import struct

# Constants
HTTP_PORT = 8000
DEBUG_PORT = 8001

# Debug adapter protocol version
DEBUG_PROTOCOL_VERSION = 1

# Data formats
DATA_FORMAT = '!BBI'
DATA_SIZE = 4

class DebugAdapter:
    def __init__(self, host='localhost', port=DEBUG_PORT):
        self.host = host
        self.port = port
        self.socket = None

    def start(self):
        self.socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.socket.bind((self.host, self.port))
        self.socket.listen(1)

    def accept_connection(self):
        client_socket, address = self.socket.accept()
        return client_socket

class DebugProtocol:
    def __init__(self, client_socket):
        self.client_socket = client_socket

    def send_message(self, message):
        self.client_socket.sendall(message)

    def receive_message(self, length):
        return self.client_socket.recv(length)

class Message:
    def __init__(self, data, data_length, data_type):
        self.data = data
        self.data_length = data_length
        self.data_type = data_type

    def pack(self):
        return struct.pack(DATA_FORMAT, self.data_type, self.data_length) + self.data

    def unpack(self, data):
        data = data[4:]
        data_type, data_length = struct.unpack(DATA_FORMAT, data[:DATA_SIZE])
        return Message(data=data[data_size:], data_length=data_length, data_type=data_type)

class Command(Message):
    def __init__(self, command_id, data):
        super().__init__(data=data, data_length=0, data_type=None)
        self.command_id = command_id

    def pack(self):
        return super().pack() + struct.pack('B', self.command_id)

    def unpack(self, data):
        return Command(command_id=struct.unpack('B', data[:1])[0], data=super().unpack(data)[1:])

class Request(Message):
    def __init__(self, command, request_id):
        super().__init__(data=command.pack(), data_length=len(command.pack()), data_type='request')
        self.request_id = request_id

    def pack(self):
        return super().pack()

    def unpack(self, data):
        return Request(command=Command.unpack(data), request_id=struct.unpack('I', data[:4])[0])

class Response(Message):
    def __init__(self, command, response_id):
        super().__init__(data=command.pack(), data_length=len(command.pack()), data_type='response')
        self.response_id = response_id

    def pack(self):
        return super().pack()

    def unpack(self, data):
        return Response(command=Command.unpack(data), response_id=struct.unpack('I', data[:4])[0])

class MessageHandler:
    def __init__(self, protocol):
        self.protocol = protocol

    def handle_command(self, command):
        if command.command_id == 1:
            return Response(command=Command(command_id=1, data=b'Command received'), response_id=1)
        elif command.command_id == 2:
            return Response(command=Command(command_id=2, data=b'Request received'), response_id=1)
        else:
            return Response(command=Command(command_id=3, data=b'Unknown command'), response_id=1)

    def handle_request(self, request):
        response = Response(command=Command(command_id=4, data=b'Response sent'), response_id=1)
        return response

def main():
    adapter = DebugAdapter()
    adapter.start()
    client_socket = adapter.accept_connection()

    protocol = DebugProtocol(client_socket)

    message_handler = MessageHandler(protocol)

    while True:
        readable, writable, errored = select.select([protocol.client_socket], [], [], 0)
        if readable:
            data = protocol.receive_message(1024)
            message = Message.unpack(data)
            if message.data_type == 'request':
                response = message_handler.handle_request(message)
                protocol.send_message(response.pack())
            elif message.data_type == 'response':
                print('Received response:', message.data)
            else:
                print('Received unknown message:', message.data)

if __name__ == '__main__':
    main()
```

This code implements a basic debug adapter for Python using the Debug Adapter Protocol (DAP) specification. It listens for incoming connections on a socket, accepts connections, and handles requests and responses. The `MessageHandler` class encapsulates the logic for handling commands and requests.

