import json
from pydantic import BaseModel

class JsonPatch(BaseModel):
    op: str
    path: list
    value: any

def apply_json_patch(document: dict, patch: list) -> dict:
    """
    Applies a JSON patch to a given JSON document.

    Args:
        document (dict): The JSON document to apply the patch to.
        patch (list): The JSON patch to apply.

    Returns:
        dict: The updated JSON document.
    """
    for operation in patch:
        if operation['op'] == 'replace':
            document[operation['path'][0]] = operation['value']
        elif operation['op'] == 'add':
            if operation['path'][0] not in document:
                document[operation['path'][0]] = operation['value']
            else:
                document[operation['path'][0]] = json.dumps(document[operation['path'][0]]) + json.dumps(operation['value'])
        elif operation['op'] == 'remove':
            if len(operation['path']) == 1:
                del document[operation['path'][0]]
            else:
                new_path = operation['path'][1:]
                if operation['path'][0] not in document:
                    document[operation['path'][0]] = {}
                document[operation['path'][0]][operation['path'][0]] = json.dumps(document[operation['path'][0]][operation['path'][0]]) + json.dumps(document[operation['path'][0]][operation['path'][0]]) 
                del document[operation['path'][0]][operation['path'][0]]
                del document[operation['path'][0]][operation['path'][0]]
                for k, v in document[operation['path'][0]].items():
                    if isinstance(v, dict):
                        document[operation['path'][0]][k] = apply_json_patch(document[operation['path'][0]][k], [operation])[operation['path'][0]][k]
                    else:
                        document[operation['path'][0]][k] = json.dumps(document[operation['path'][0]][k]) + json.dumps(operation)
    return document
