```python
import json

class JSONParser:
    def __init__(self, json_str):
        self.json_str = json_str
        self.index = 0
        self.stack = []

    def __iter__(self):
        return self

    def __next__(self):
        while self.index < len(self.json_str):
            if self.json_str[self.index] == '{':
                self.stack.append(self.json_str[self.index])
                self.index += 1
                while self.index < len(self.json_str) and self.json_str[self.index] != '}':
                    self.index += 1
                if self.json_str[self.index] != '}':
                    raise ValueError("Invalid JSON string")
                self.index += 1
                self.stack.pop()
            elif self.json_str[self.index] == '[':
                self.index += 1
                while self.index < len(self.json_str) and self.json_str[self.index] != ']':
                    self.index += 1
                if self.json_str[self.index] != ']':
                    raise ValueError("Invalid JSON string")
                self.index += 1
            elif self.json_str[self.index] == ',':
                self.index += 1
            else:
                self.index += 1
                if self.json_str[self.index].isspace():
                    continue
                yield self.json_str[self.index]
                while self.index < len(self.json_str) and not self.json_str[self.index].isspace():
                    self.index += 1
        raise StopIteration

def parse_json(json_str):
    parser = JSONParser(json_str)
    for item in parser:
        yield json.loads(item)

# Example usage:
json_str = '{"name": "John", "age": 30, "city": "New York"}'
for item in parse_json(json_str):
    print(item)
```

```python
from fuzzywuzzy import fuzz
from fuzzywuzzy import process
from sklearn.metrics.pairwise import cosine_similarity
import numpy as np

def levenshtein_distance(s1, s2):
    if len(s1) < len(s2):
        return levenshtein_distance(s2, s1)

    if len(s2) == 0:
        return len(s1)

    previous_row = range(len(s2) + 1)
    for i, c1 in enumerate(s1):
        current_row = [i + 1]
        for j, c2 in enumerate(s2):
            insertions = previous_row[j + 1] + 1 
            deletions = current_row[j] + 1 
            substitutions = previous_row[j] + (c1 != c2)
            current_row.append(min(insertions, deletions, substitutions))
        previous_row = current_row

    return previous_row[-1]

def jaccard_similarity(s1, s2):
    set1 = set(s1)
    set2 = set(s2)
    intersection = set1.intersection(set2)
    union = set1.union(set2)
    return len(intersection) / len(union)

def cosine_similarity_matrix(texts):
    return cosine_similarity(texts)

def fuzzy_match(text1, text2, threshold=80, ignore_duplicates=False):
    score = fuzz.partial_ratio(text1, text2)
    if score >= threshold:
        return score
    else:
        return None

def advanced_fuzzy_match(text1, text2, threshold=80, ignore_duplicates=False):
    scores = process.extractOne(text1, [text2], scorer=fuzz.token_sort_ratio)
    if ignore_duplicates and scores[0][1] == 100:
        return None
    else:
        return scores[0][1]

def advanced_fuzzy_match_matrix(texts, threshold=80, ignore_duplicates=False):
    scores = []
    for text in texts:
        scores_text = process.extract(text, texts, scorer=fuzz.token_sort_ratio)
        if ignore_duplicates:
            filtered_scores = [(text, score) for text, score in scores_text if score != 100]
        else:
            filtered_scores = scores_text
        scores.extend(filtered_scores)
    return scores
