import requests

def send_get_request(url):
    try:
        response = requests.get(url)
        print(f"GET Request to {url} returned status code {response.status_code}")
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f"Error: {e}")
        return None

def send_post_request(url, data):
    try:
        response = requests.post(url, json=data)
        print(f"POST Request to {url} returned status code {response.status_code}")
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f"Error: {e}")
        return None

def send_put_request(url, data):
    try:
        response = requests.put(url, json=data)
        print(f"PUT Request to {url} returned status code {response.status_code}")
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f"Error: {e}")
        return None

def send_delete_request(url):
    try:
        response = requests.delete(url)
        print(f"DELETE Request to {url} returned status code {response.status_code}")
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f"Error: {e}")
        return None

# Example usage
url = "http://httpbin.org"
data = {"key": "value"}

print("GET Request:")
get_response = send_get_request(url)
print(get_response)

print("\nPOST Request:")
post_response = send_post_request(url, data)
print(post_response)

print("\nPUT Request:")
put_response = send_put_request(url, data)
print(put_response)

print("\nDELETE Request:")
delete_response = send_delete_request(url)
print(delete_response)
