import numpy as np
import tensorflow as tf

class Tensor:
    def __init__(self, data):
        self.data = np.array(data)

    def __add__(self, other):
        if isinstance(other, Tensor):
            return Tensor(self.data + other.data)
        else:
            return Tensor(self.data + other)

    def __sub__(self, other):
        if isinstance(other, Tensor):
            return Tensor(self.data - other.data)
        else:
            return Tensor(self.data - other)

    def __mul__(self, other):
        if isinstance(other, Tensor):
            return Tensor(self.data * other.data)
        else:
            return Tensor(self.data * other)

class DynamicNN:
    def __init__(self, input_shape, output_shape):
        self.input_shape = input_shape
        self.output_shape = output_shape
        self.layers = []

    def add_layer(self, layer):
        self.layers.append(layer)

    def forward(self, x):
        for layer in self.layers:
            x = layer.forward(x)
        return x

class DenseLayer:
    def __init__(self, num_inputs, num_outputs, activation=None):
        self.num_inputs = num_inputs
        self.num_outputs = num_outputs
        self.activation = activation
        self.weights = tf.Variable(tf.random.normal([num_inputs, num_outputs]))
        self.bias = tf.Variable(tf.random.normal([num_outputs]))

    def forward(self, x):
        output = tf.matmul(x, self.weights) + self.bias
        if self.activation:
            output = self.activation(output)
        return output

class Conv2DLayer:
    def __init__(self, num_filters, kernel_size, activation=None):
        self.num_filters = num_filters
        self.kernel_size = kernel_size
        self.activation = activation
        self.weights = tf.Variable(tf.random.normal([num_filters, kernel_size, kernel_size, 1]))
        self.bias = tf.Variable(tf.random.normal([num_filters]))

    def forward(self, x):
        output = tf.nn.conv2d(x, self.weights, strides=[1, 1, 1, 1], padding='SAME')
        output = tf.nn.bias_add(output, self.bias)
        if self.activation:
            output = self.activation(output)
        return output

# Example usage
input_shape = (28, 28, 1)
output_shape = (10,)
hidden_layers = [DenseLayer(784, 128, activation=tf.nn.relu), DenseLayer(128, 64, activation=tf.nn.relu)]
output_layer = DenseLayer(64, 10, activation=tf.nn.softmax)
model = DynamicNN(input_shape, output_shape)
for layer in hidden_layers:
    model.add_layer(layer)
model.add_layer(output_layer)

x = Tensor(np.random.rand(1, 28, 28, 1))
y_pred = model.forward(x)
print(y_pred)
```

