```python
class Promise:
    def __init__(self, callback):
        self.callback = callback
        self.result = None
        self.error = None
        self.fulfilled = False
        self.rejected = False
        self.pending = 1

    def then(self, callback):
        if not self.fulfilled and not self.rejected:
            self.pending -= 1
            newPromise = Promise(self.callback)
            newPromise.fulfilled = False
            newPromise.rejected = False
            newPromise.callback = callback
            return newPromise
        else:
            return callback(self.result if self.fulfilled else None)

    def catch(self, callback):
        if not self.fulfilled and not self.rejected:
            self.pending -= 1
            newPromise = Promise(self.callback)
            newPromise.fulfilled = False
            newPromise.rejected = False
            newPromise.callback = callback
            return newPromise
        else:
            return callback(self.error if self.rejected else None)

    def resolve(self, value):
        if not self.rejected:
            self.fulfilled = True
            self.result = value
            self.pending -= 1
            if self.pending == 0:
                self.callback(value)

    def reject(self, reason):
        if not self.fulfilled:
            self.rejected = True
            self.error = reason
            self.pending -= 1
            if self.pending == 0:
                self.callback(reason)


def createPromise(callback):
    return Promise(callback)


def main():
    # Create a promise
    promise = createPromise(lambda x: x * 2)

    # Register callbacks
    promise.then(lambda x: print(x)).then(lambda x: print(x))
    promise.catch(lambda e: print(e))

    # Resolve the promise
    promise.resolve(10)

    # Reject the promise
    promise.reject("Error")


if __name__ == "__main__":
    main()
```

```python
import pubsub

class PubSub:
    def __init__(self):
        self.pubsub = pubsub.PubSub()

    def publish(self, channel, message):
        self.pubsub.publish(channel, message)

    def subscribe(self, channel, callback):
        self.pubsub.subscribe(channel, callback)

    def unsubscribe(self, channel, callback):
        self.pubsub.unsubscribe(channel, callback)

class Publisher(PubSub):
    def __init__(self):
        super().__init__()
        self.channels = {}

    def publish(self, channel, message):
        if channel not in self.channels:
            self.channels[channel] = []
        self.channels[channel].append(message)

    def get_messages(self, channel):
        return self.channels.get(channel, [])

class Subscriber(PubSub):
    def __init__(self):
        super().__init__()
        self.channels = {}

    def subscribe(self, channel, callback):
        if channel not in self.channels:
            self.channels[channel] = []
        self.channels[channel].append(callback)

    def unsubscribe(self, channel, callback):
        if channel in self.channels:
            self.channels[channel].remove(callback)

    def receive(self, channel):
        if channel in self.channels:
            for message in self.channels[channel]:
                callback(message)

class ObjectToObject:
    def __init__(self):
        self.publisher = Publisher()
        self.subscriber = Subscriber()

    def publish_to(self, obj, channel, message):
        self.publisher.publish(channel, message)

    def subscribe_to(self, obj, channel, callback):
        self.subscriber.subscribe(channel, callback)

    def receive_from(self, obj, channel):
        self.subscriber.receive(channel)

class Broadcast:
    def __init__(self):
        self.publisher = Publisher()

    def publish_to_all(self, message):
        self.publisher.publish('all', message)

    def subscribe_to_all(self, callback):
        self.publisher.subscribe('all', callback)

    def receive_from_all(self):
        return self.publisher.get_messages('all')

# Example usage:
publisher = Broadcast()
publisher.subscribe_to_all(lambda message: print(f"Received message: {message}"))

obj = ObjectToObject()
obj.subscribe_to('channel', lambda message: print(f"Received message from channel: {message}"))
obj.publish_to('channel', "Hello, world!")

publisher.publish_to_all("Hello, everyone!")
obj.publish_to('channel', "Hello, world!")

obj.receive_from('channel')
publisher.receive_from_all()
```

