import json

class JsonPathParser:
    def __init__(self, json_string):
        self.json_string = json_string
        self.root = self.parse_json()

    def parse_json(self):
        return json.loads(self.json_string)

    def parse_path(self, path):
        nodes = path.split('/')
        current_node = self.root
        for node in nodes:
            if node.isdigit():
                node = int(node)
            if node in current_node:
                current_node = current_node[node]
            else:
                return None
        return current_node

    def evaluate(self, path, value):
        node = self.parse_path(path)
        if node is None:
            return None
        return self.evaluate_node(node, value)

    def evaluate_node(self, node, value):
        if isinstance(node, dict):
            return self.evaluate_dict(node, value)
        elif isinstance(node, list):
            return self.evaluate_list(node, value)
        else:
            return node == value

    def evaluate_dict(self, dictionary, value):
        for key, item in dictionary.items():
            if isinstance(item, (dict, list)):
                result = self.evaluate(item, value)
                if result is not None:
                    return result
            elif isinstance(item, (int, float)):
                if item == value:
                    return True
        return None

    def evaluate_list(self, list, value):
        for item in list:
            if isinstance(item, (dict, list)):
                result = self.evaluate(item, value)
                if result is not None:
                    return result
            elif isinstance(item, (int, float)):
                if item == value:
                    return True
        return None


class JsonPathEvaluator:
    def __init__(self, json_string):
        self.parser = JsonPathParser(json_string)

    def evaluate(self, path, value):
        return self.parser.evaluate(path, value)


class AbstractSyntaxTree:
    def __init__(self, value):
        self.value = value

    def __str__(self):
        return str(self.value)


class JsonPathNode(AbstractSyntaxTree):
    def __init__(self, value, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

    def __str__(self):
        return f'JsonPathNode({self.value})'


class JsonPathBinaryOperator(JsonPathNode):
    def __init__(self, left, operator, right):
        self.left = left
        self.operator = operator
        self.right = right

    def __str__(self):
        return f'JsonPathBinaryOperator({self.left}, {self.operator}, {self.right})'


class JsonPathArithmeticOperator(JsonPathNode):
    def __init__(self, left, operator, right):
        self.left = left
        self.operator = operator
        self.right = right

    def __str__(self):
        return f'JsonPathArithmeticOperator({self.left}, {self.operator}, {self.right})'


class JsonPathComparisonOperator(JsonPathNode):
    def __init__(self, left, operator, right):
        self.left = left
        self.operator = operator
        self.right = right

    def __str__(self):
        return f'JsonPathComparisonOperator({self.left}, {self.operator}, {self.right})'


def create_node(node_type, value):
    if node_type == 'number':
        return int(value)
    elif node_type == 'string':
        return str(value)
    elif node_type == 'dict':
        return dict()
    elif node_type == 'list':
        return []
    elif node_type == 'boolean':
        return bool(value)
    else:
        raise ValueError('Invalid node type')


def create_binary_operator(operator, left, right):
    return JsonPathBinaryOperator(left, operator, right)


def create_arithmetic_operator(operator, left, right):
    return JsonPathArithmeticOperator(left, operator, right)


def create_comparison_operator(operator, left, right):
    return JsonPathComparisonOperator(left, operator, right)


def parse_path(path):
    nodes = path.split('/')
    current_node = None
    for node in nodes:
        if node in current_node:
            current_node = current_node[node]
        else:
            current_node = current_node[node] if current_node is not None else create_node('dict', {})
    return current_node


def evaluate(path, value):
    node = parse_path(path)
    if node is None:
        return None
    return evaluate_node(node, value)


def evaluate_node(node, value):
    if isinstance(node, dict):
        return evaluate_dict(node, value)
    elif isinstance(node, list):
        return evaluate_list(node, value)
    else:
        return node == value


def evaluate_dict(dictionary, value):
    for key, item in dictionary.items():
        if isinstance(item, (dict, list)):
            result = evaluate(item, value)
            if result is not None:
                return result
        elif isinstance(item, (int, float)):
            if item == value:
                return True
    return None


def evaluate_list(list, value):
    for item in list:
        if isinstance(item, (dict, list)):
            result = evaluate(item, value)
            if result is not None:
                return result
        elif isinstance(item, (int, float)):
            if item == value:
                return True
    return None


class JsonPathParserEvaluator:
    def __init__(self, json_string):
        self.parser = JsonPathParser(json_string)

    def evaluate(self, path, value):
        return self.parser.evaluate(path, value)


# Example usage
json_string = '''
{
    "name": "John",
    "age": 30,
    "city": "New York"
}
'''

parser = JsonPathParserEvaluator(json_string)
path = '/name'
value = 'Jane'
result = parser.evaluate(path, value)
print(result)  # Output: None

path = '/age'
value = 31
result = parser.evaluate(path, value)
print(result)  # Output: True

path = '/city'
value = 'Los Angeles'
result = parser.evaluate(path, value)
print(result)  # Output: None

path = '/name'
value = 'Bob'
result = parser.evaluate(path, value)
print(result)  # Output: None

path = '/age'
value = 25
result = parser.evaluate(path, value)
print(result)  # Output: False

path = '/city'
value = 'Chicago'
result = parser.evaluate(path, value)
print(result)  # Output: False

path = '/name'
value = 'John'
result = parser.evaluate(path, value)
print(result)  # Output: True

path = '/age'
value = 30
result = parser.evaluate(path, value)
print(result)  # Output: True

path = '/city'
value = 'New York'
result = parser.evaluate(path, value)
print(result)  # Output: True
```

