import unicodedata
import csv

def normalize_unicode(s):
    return unicodedata.normalize('NFKD', s).encode('ascii', 'ignore').decode('utf-8')

class UnicodeCSVWriter:
    def __init__(self, file, encoding='utf-8', dialect=None):
        self.file = file
        self.encoding = encoding
        self.dialect = dialect or csv.excel

    def writeheader(self, fieldnames):
        writer = csv.DictWriter(self.file, fieldnames=fieldnames, dialect=self.dialect, quoting=csv.QUOTE_ALL)
        writer.writeheader()

    def writerow(self, row):
        writer = csv.DictWriter(self.file, dialect=self.dialect, quoting=csv.QUOTE_ALL)
        writer.writerow(row)

class UnicodeCSVReader:
    def __init__(self, file, dialect=None):
        self.file = file
        self.dialect = dialect or csv.excel

    def read(self):
        reader = csv.reader(self.file, dialect=self.dialect)
        for row in reader:
            yield [normalize_unicode(s) for s in row]

def read_csv(file, dialect=None):
    return UnicodeCSVReader(file, dialect=dialect)

def write_csv(file, fieldnames, data, dialect=None, encoding='utf-8'):
    writer = UnicodeCSVWriter(file, dialect=dialect, encoding=encoding)
    writer.writeheader(fieldnames)
    for row in data:
        writer.writerow(row)

# Usage
with open('output.csv', 'w', newline='', encoding='utf-8') as file:
    write_csv(file, ['Name', 'Age'], [
        ['John', 30],
        ['Alice', 25],
    ])

with open('output.csv', 'r', newline='', encoding='utf-8') as file:
    reader = read_csv(file)
    for row in reader.read():
        print(row)
```

