import os
import sys
from typing import Dict, List
from setuptools import setup, find_packages
from poetry.core.masonry import MasonryProject
from poetry.core.masonry import MasonryEnvironment

class PoeticMasonryProject(MasonryProject):
    name: str = "poetic"
    version: str = "0.1.0"

    def __init__(self, path: str):
        super().__init__(path)

    def _get_info(self) -> Dict:
        return {
            "name": self.name,
            "version": self.version,
            "description": "A Poetic backend for building Python packages",
            "classifiers": [
                "Development Status :: 5 - Production/Stable",
                "Intended Audience :: Developers",
                "License :: OSI Approved :: MIT License",
                "Programming Language :: Python :: 3.7",
                "Programming Language :: Python :: 3.8",
                "Programming Language :: Python :: 3.9",
                "Programming Language :: Python :: 3.10",
            ],
            "packages": find_packages(),
        }

    def _get_install_requires(self) -> List[str]:
        return []

    def _get_urls(self) -> Dict[str, str]:
        return {
            "Source": "https://github.com/poetic/poetic",
            "Bug Reports": "https://github.com/poetic/poetic/issues",
            "Changelogs": "https://github.com/poetic/poetic/releases",
        }

    def _get_package_data(self) -> Dict[str, List[str]]:
        return {"": ["poetic/*"]}

    def _get_metadata(self) -> Dict:
        return {
            "name": self.name,
            "version": self.version,
            "description": self.description,
            "long_description": open("README.rst").read(),
            "author": "Your Name",
            "author_email": "your@email.com",
            "license": "MIT",
            "classifiers": self.classifiers,
        }

def main():
    if len(sys.argv) != 2:
        print("Usage: python setup.py <command>")
        sys.exit(1)

    command = sys.argv[1]
    project = PoeticMasonryProject(".")
    environment = MasonryEnvironment(project)

    if command == "sdist":
        environment.sdist()
    elif command == "bdist_wheel":
        environment.bdist_wheel()
    elif command == "build":
        environment.build()
    else:
        print("Unknown command")
        sys.exit(1)

if __name__ == "__main__":
    main()
```

