import os
import pickle
from google.oauth2 import service_account
from googleapiclient.discovery import build
from googleapiclient.errors import HttpError

# Replace with your service account credentials
creds = service_account.Credentials.from_service_account_file(
    'path_to_your_service_account_key.json',
    scopes=['https://www.googleapis.com/auth/spreadsheets']
)

# Initialize the Sheets API client
service = build('sheets', 'v4', credentials=creds)

def get_service_account_credentials():
    return creds

def list_sheets(service, spreadsheet_id):
    """List all sheets in a spreadsheet."""
    response = service.spreadsheets().values().list(spreadsheetId=spreadsheet_id).execute()
    sheets = []
    for item in response.get('values', []):
        if item[0] != '':
            sheets.append(item[0])
    return sheets

def create_sheet(service, spreadsheet_id, sheet_name):
    """Create a new sheet in a spreadsheet."""
    body = {
        'properties': {
            'title': sheet_name
        }
    }
    try:
        service.spreadsheets().values().update(
            spreadsheetId=spreadsheet_id,
            range=f"'{sheet_name}'!",
            body=body
        ).execute()
        print(f"Sheet '{sheet_name}' created successfully.")
    except HttpError as error:
        print(f"Failed to create sheet '{sheet_name}': {error}")

def delete_sheet(service, spreadsheet_id, sheet_name):
    """Delete a sheet from a spreadsheet."""
    try:
        service.spreadsheets().values().update(
            spreadsheetId=spreadsheet_id,
            range=f"'{sheet_name}'!",
            body={'properties': {'title': ''}}
        ).execute()
        print(f"Sheet '{sheet_name}' deleted successfully.")
    except HttpError as error:
        print(f"Failed to delete sheet '{sheet_name}': {error}")

def rename_sheet(service, spreadsheet_id, old_name, new_name):
    """Rename a sheet in a spreadsheet."""
    body = {
        'properties': {
            'title': new_name
        }
    }
    try:
        service.spreadsheets().values().update(
            spreadsheetId=spreadsheet_id,
            range=f"'{old_name}'!",
            body=body
        ).execute()
        print(f"Sheet '{old_name}' renamed to '{new_name}' successfully.")
    except HttpError as error:
        print(f"Failed to rename sheet '{old_name}': {error}")

def format_cell(service, spreadsheet_id, sheet_name, row, col, value):
    """Format a cell with a value."""
    body = {
        'values': [
            {
                'userEnteredValue': {
                    'stringValue': value
                }
            }
        ]
    }
    try:
        service.spreadsheets().values().update(
            spreadsheetId=spreadsheet_id,
            range=f"{sheet_name}!{row},{col}",
            valueInputOption='USER_ENTERED',
            body=body
        ).execute()
        print(f"Cell '{row},{col}' in sheet '{sheet_name}' formatted successfully.")
    except HttpError as error:
        print(f"Failed to format cell '{row},{col}': {error}")

def format_sheet(service, spreadsheet_id, sheet_name, header):
    """Format a sheet with a header."""
    body = {
        'properties': {
            'title': header
        }
    }
    try:
        service.spreadsheets().values().update(
            spreadsheetId=spreadsheet_id,
            range=f"'{sheet_name}'!",
            body=body
        ).execute()
        print(f"Sheet '{sheet_name}' formatted successfully.")
    except HttpError as error:
        print(f"Failed to format sheet '{sheet_name}': {error}")

def add_sheet(service, spreadsheet_id, sheet_name):
    """Add a new sheet to a spreadsheet."""
    body = {
        'properties': {
            'title': sheet_name
        }
    }
    try:
        service.spreadsheets().values().update(
            spreadsheetId=spreadsheet_id,
            range=f"'{sheet_name}'!",
            body=body
        ).execute()
        print(f"Sheet '{sheet_name}' added successfully.")
    except HttpError as error:
        print(f"Failed to add sheet '{sheet_name}': {error}")

def main():
    spreadsheet_id = 'your_spreadsheet_id'
    sheet_name = 'your_sheet_name'

    sheets = list_sheets(service, spreadsheet_id)
    print(f"Current sheets: {sheets}")

    create_sheet(service, spreadsheet_id, 'new_sheet')
    print(f"Created new sheet: {list_sheets(service, spreadsheet_id)}")

    delete_sheet(service, spreadsheet_id, 'old_sheet')
    print(f"Deleted old sheet: {list_sheets(service, spreadsheet_id)}")

    rename_sheet(service, spreadsheet_id, 'old_sheet', 'new_sheet')
    print(f"Renamed old sheet: {list_sheets(service, spreadsheet_id)}")

    format_cell(service, spreadsheet_id, 'new_sheet', 1, 1, 'Hello, World!')
    format_sheet(service, spreadsheet_id, 'new_sheet', 'Hello, World!')

    add_sheet(service, spreadsheet_id, 'another_sheet')
    print(f"Added new sheet: {list_sheets(service, spreadsheet_id)}")

if __name__ == "__main__":
    main()
```

