import ast

class Unparser(ast.NodeTransformer):
    def visit_FunctionDef(self, node):
        # Convert function definition to source code
        source = f"def {node.name}("
        for arg in node.args.args:
            source += f"{arg.arg}, "
        source += f"):"
        source += "\n"
        for child in ast.iter_child_nodes(node):
            source += self.visit(child) + "\n"
        source += "{"
        for child in ast.iter_child_nodes(node):
            source += self.visit(child) + "\n"
        source += "}"
        return source

    def visit_ClassDef(self, node):
        # Convert class definition to source code
        source = f"class {node.name}:\n"
        for child in ast.iter_child_nodes(node):
            source += self.visit(child) + "\n"
        source += "    pass"
        return source

    def visit_If(self, node):
        # Convert if statement to source code
        source = f"if {node.test}:\n"
        for child in ast.iter_child_nodes(node):
            source += self.visit(child) + "\n"
        return source

    def visit_For(self, node):
        # Convert for loop to source code
        source = f"for {node.target.id} in {node.iter}:"
        for child in ast.iter_child_nodes(node):
            source += "\n" + self.visit(child)
        return source

    def visit_While(self, node):
        # Convert while loop to source code
        source = f"while {node.test}:\n"
        for child in ast.iter_child_nodes(node):
            source += self.visit(child) + "\n"
        return source

    def visit_With(self, node):
        # Convert with statement to source code
        source = f"with {node.items[0].id} as {node targets[0].id}:\n"
        for child in ast.iter_child_nodes(node):
            source += self.visit(child) + "\n"
        return source

    def visit_Expr(self, node):
        # Convert expression to source code
        if isinstance(node.value, ast.Call):
            # Convert function call to source code
            source = f"{node.value.func.id}({', '.join(f'{self.visit(child)}' for child in ast.iter_child_nodes(node.value))})"
        else:
            # Convert other expressions to source code
            source = str(node.value)
        return source

    def visit_Name(self, node):
        # Convert name to source code
        return node.id

    def generic_visit(self, node):
        # Handle other node types
        return str(node)

def unparse(node):
    return Unparser().visit(node)

# Example usage
code = unparse(ast.parse("x = 5"))
print(code)
