import ipaddress
import dns.resolver

def convert_ip_address(ip):
    """Converts an IP address from one format to another."""
    try:
        ip_obj = ipaddress.ip_address(ip)
        if isinstance(ip_obj, ipaddress.IPv4Address):
            return ip_obj.exploded
        elif isinstance(ip_obj, ipaddress.IPv6Address):
            return ip_obj.exploded
        else:
            raise ValueError("Unsupported IP address type")
    except ValueError:
        try:
            return ipaddress.ip_address(ip)
        except ValueError:
            return "Invalid IP address"

def perform_dns_lookup(hostname):
    """Performs a DNS lookup on a given hostname."""
    try:
        answer = dns.resolver.resolve(hostname, 'A')
        return str(list(answer)[0])
    except dns.resolver.NoAnswer:
        return "No A record found"
    except dns.resolver.NXDOMAIN:
        return "Hostname not found"

def calculate_subnet_mask(ip, cidr):
    """Calculates the subnet mask for a given IP address and CIDR prefix."""
    ip_obj = ipaddress.ip_address(ip)
    subnet = ipaddress.ip_network(f"{ip_obj}/{cidr}", strict=False)
    return str(subnet.netmask)

# Example usage:
print(convert_ip_address("192.168.1.1"))  # Output: 192.168.1.1
print(convert_ip_address("2001:0db8:85a3:0000:0000:8a2e:0370:7334"))  # Output: 2001:0db8:85a3:0:0:8a2e:370:7334
print(perform_dns_lookup("www.google.com"))  # Output: 216.58.194.174
print(calculate_subnet_mask("192.168.1.1", 24))  # Output: 255.255.255.0
