import sys
import os

def detect_shell():
    if os.name == 'posix' and sys.platform == 'darwin':
        return 'fish'
    elif os.name == 'posix' and sys.platform in ['linux', 'freebsd']:
        if '$PS1' in os.environ:
            return 'zsh'
        elif '$CSH' in os.environ:
            return 'tcsh'
        else:
            return 'sh'
    else:
        return None

print(detect_shell())
