```python
import logging
import json
from logging.handlers import MemoryHandler, RotatingFileHandler
from datetime import datetime

class JSONFormatter(logging.Formatter):
    def format(self, record):
        if record.levelname == 'CRITICAL':
            level_icon = '\033[91m'  # Red color
        elif record.levelname == 'ERROR':
            level_icon = '\033[93m'  # Yellow color
        elif record.levelname == 'WARNING':
            level_icon = '\033[93m'  # Yellow color
        elif record.levelname == 'INFO':
            level_icon = '\033[0m'  # Default color
        else:
            level_icon = '\033[0m'  # Default color

        formatted_message = {
            'timestamp': datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S'),
            'level': record.levelname,
            'level_icon': level_icon,
            'message': record.getMessage()
        }

        return json.dumps(formatted_message)

class CustomLogger:
    def __init__(self, name, level=logging.INFO, timestamp_format='%Y-%m-%d %H:%M:%S', log_level_icon=None):
        self.logger = logging.getLogger(name)
        self.logger.setLevel(level)
        self.timestamp_format = timestamp_format
        self.log_level_icon = log_level_icon

        self.handler = MemoryHandler(maxBytes=1000000, backupCount=5)
        self.handler.setFormatter(JSONFormatter('%(message)s'))

        self.logger.addHandler(self.handler)

    def debug(self, message):
        self.logger.debug(message)

    def info(self, message):
        self.logger.info(message)

    def warning(self, message):
        self.logger.warning(message)

    def error(self, message):
        self.logger.error(message)

    def critical(self, message):
        self.logger.critical(message)

# Usage
logger = CustomLogger('my_logger')
logger.debug('This is a debug message')
logger.info('This is an info message')
logger.warning('This is a warning message')
logger.error('This is an error message')
logger.critical('This is a critical message')
```

```python
import requests
import xmltodict

def get_geographic_data(address, api_key):
    # OpenStreetMap API
    url = f"https://nominatim.openstreetmap.org/search?q={address}&format=json&limit=1"
    response = requests.get(url)
    data = response.json()

    if data:
        lat = data[0]['lat']
        lon = data[0]['lon']

        # Google Maps API
        google_url = f"https://maps.googleapis.com/maps/api/geocode/json?address={address}&key={api_key}"
        google_response = requests.get(google_url)
        google_data = google_response.json()

        if google_data['status'] == 'OK':
            lat = google_data['results'][0]['geometry']['location']['lat']
            lon = google_data['results'][0]['geometry']['location']['lng']

        return {
            'osm': {
                'lat': lat,
                'lon': lon
            },
            'google': {
                'lat': lat,
                'lon': lon
            }
        }

    return None

def parse_geographic_data(data, format):
    if format == 'xml':
        return xmltodict.parse(data)

    return data

def main():
    address = input("Enter an address: ")
    api_key = input("Enter your Google Maps API key: ")

    data = get_geographic_data(address, api_key)

    if data:
        print("Geographic Data:")
        print(parse_geographic_data(data['osm'], 'xml'))
        print(parse_geographic_data(data['google'], 'json'))
    else:
        print("No geographic data found.")

if __name__ == "__main__":
    main()
```

