class EventBus:
    def __init__(self):
        self.subscribers = {}

    def subscribe(self, event_type, subscriber):
        if event_type not in self.subscribers:
            self.subscribers[event_type] = []
        self.subscribers[event_type].append(subscriber)

    def unsubscribe(self, event_type, subscriber):
        if event_type in self.subscribers:
            self.subscribers[event_type].remove(subscriber)

    def publish(self, event_type, *args, **kwargs):
        if event_type in self.subscribers:
            for subscriber in self.subscribers[event_type]:
                subscriber(*args, **kwargs)


class Subscriber:
    def __init__(self, name):
        self.name = name

    def __call__(self, *args, **kwargs):
        print(f"{self.name} received event: {args}, {kwargs}")


def main():
    event_bus = EventBus()

    subscriber1 = Subscriber("Subscriber 1")
    subscriber2 = Subscriber("Subscriber 2")

    event_bus.subscribe("event_type_1", subscriber1)
    event_bus.subscribe("event_type_1", subscriber2)

    event_bus.publish("event_type_1", "Hello, world!")
    event_bus.publish("event_type_2", "Goodbye, world!")


if __name__ == "__main__":
    main()
```

```python
import weakref
import sys

class WeakRef:
    """
    A weak reference implementation for Python.
    """
    def __init__(self, obj, delta=0):
        self.obj = obj
        self.delta = delta
        self.ref_count = 0
        self.cache = None

    def __get__(self, instance, owner):
        if instance is None:
            return self
        try:
            return instance.__dict__[self.delta]
        except KeyError:
            raise AttributeError(f"Attribute '{self.delta}' not found")

    def __set__(self, instance, value):
        instance.__dict__[self.delta] = value

    def __del__(self):
        pass

    def __repr__(self):
        return f"WeakRef({self.obj.__class__.__name__}, {self.delta})"

class WeakKeyDict(dict):
    """
    A dictionary with weak keys.
    """
    def __init__(self, delta=0):
        self.delta = delta
        self.ref_count = 0
        self.cache = {}

    def __setitem__(self, key, value):
        if key not in self.cache:
            self.cache[key] = WeakRef(value, delta=self.delta)
        self.ref_count += 1

    def __delitem__(self, key):
        if key in self.cache:
            self.ref_count -= 1
            if self.ref_count == 0:
                del self.cache[key]

    def __getitem__(self, key):
        if key in self.cache:
            return self.cache[key].obj
        else:
            raise KeyError(key)

    def __contains__(self, key):
        return key in self.cache

    def __repr__(self):
        return f"WeakKeyDict({self.delta})"

class WeakDict(dict):
    """
    A dictionary with weak values.
    """
    def __init__(self, delta=0):
        self.delta = delta
        self.ref_count = 0
        self.cache = {}

    def __setitem__(self, key, value):
        if value not in self.cache:
            self.cache[value] = WeakRef(key, delta=self.delta)
        self.ref_count += 1

    def __delitem__(self, value):
        if value in self.cache:
            self.ref_count -= 1
            if self.ref_count == 0:
                del self.cache[value]

    def __getitem__(self, value):
        if value in self.cache:
            return self.cache[value].obj
        else:
            raise KeyError(value)

    def __contains__(self, value):
        return value in self.cache

    def __repr__(self):
        return f"WeakDict({self.delta})"

def weakref_new(obj, delta=0, weaklist=None):
    """
    A weak reference implementation for objects that are not hashable.
    """
    if weaklist is None:
        weaklist = []
    weaklist.append(WeakRef(obj, delta=delta))
    return weaklist

def weakref_new_key(obj, delta=0, weaklist=None):
    """
    A weak reference implementation for objects that are not hashable with weak keys.
    """
    if weaklist is None:
        weaklist = []
    weaklist.append(WeakRef(obj, delta=delta))
    weaklist.append(WeakKeyDict(delta=delta))
    return weaklist

def weakref_new_dict(obj, delta=0, weaklist=None):
    """
    A weak reference implementation for objects that are not hashable with weak values.
    """
    if weaklist is None:
        weaklist = []
    weaklist.append(WeakRef(obj, delta=delta))
    weaklist.append(WeakDict(delta=delta))
    return weaklist

def weakref_new_list(obj, delta=0, weaklist=None):
    """
    A weak reference implementation for objects that are not hashable with weak keys and weak values.
    """
    if weaklist is None:
        weaklist = []
    weaklist.append(WeakRef(obj, delta=delta))
    weaklist.append(WeakKeyDict(delta=delta))
    weaklist.append(WeakDict(delta=delta))
    return weaklist

# PyPy JIT compatibility
if sys.version_info[0] == 3 and sys.version_info[1] >= 7:
    from weakref import WeakKeyDictionary as WeakKeyDict
    from weakref import WeakValueDictionary as WeakDict
    from weakref import WeakReference as WeakRef
else:
    from weakref import WeakKeyDict
    from weakref import WeakDict
    from weakref import WeakRef
```

