```python
import json
import os
import subprocess
import sys
import yaml

class PreCommitHookManager:
    def __init__(self, config_file='config.yaml'):
        self.config_file = config_file
        self.config = self.load_config()
        self.hooks = {}

    def load_config(self):
        if not os.path.exists(self.config_file):
            with open(self.config_file, 'w') as f:
                json.dump({}, f)
        with open(self.config_file, 'r') as f:
            return json.load(f)

    def add_hook(self, language, hook_script):
        self.hooks[language] = hook_script
        self.save_config()

    def remove_hook(self, language):
        if language in self.hooks:
            del self.hooks[language]
        self.save_config()

    def run_hooks(self, vcs, commit_message):
        hooks_to_run = [hook for language, hook in self.hooks.items() if vcs == 'git' or vcs == 'svn']
        for hook in hooks_to_run:
            if 'shell' in hook:
                self.run_shell_hook(hook['shell'], commit_message)
            elif 'python' in hook:
                self.run_python_hook(hook['python'], commit_message)

    def run_shell_hook(self, hook_script, commit_message):
        hook_path = os.path.join(os.getcwd(), hook_script)
        if os.path.exists(hook_path):
            subprocess.check_call([hook_path], args=(commit_message,))
        else:
            print(f"Hook script {hook_path} does not exist.")

    def run_python_hook(self, hook_script, commit_message):
        hook_path = os.path.join(os.getcwd(), hook_script)
        if os.path.exists(hook_path):
            subprocess.check_call([sys.executable, hook_path], args=(commit_message,))
        else:
            print(f"Hook script {hook_path} does not exist.")

    def save_config(self):
        with open(self.config_file, 'w') as f:
            json.dump(self.hooks, f)

# Usage
if __name__ == '__main__':
    manager = PreCommitHookManager()
    manager.add_hook('python', {'shell': 'pre-commit.sh'})
    manager.add_hook('java', {'python': 'pre-commit_java.py'})
    manager.run_hooks('git', 'Commit message')
```

This code creates a class `PreCommitHookManager` that manages pre-commit hooks for multiple languages and version control systems. It loads a configuration file `config.yaml` that defines the hooks and their associated languages. The `run_hooks` method runs the hooks during the commit process, and the `add_hook` and `remove_hook` methods allow you to add and remove hooks from the configuration file. The `run_shell_hook` and `run_python_hook` methods run the hooks as shell scripts or Python scripts, respectively.

