from pydantic import BaseModel, ValidationError
import json

# Define the configuration schema
class Config(BaseModel):
    database_url: str = ""
    database_name: str = ""
    database_user: str = ""
    database_password: str = ""

    # Define validation rules
    @root_validator(pre=True)
    def validate_database_url(cls, values):
        if not values['database_url'].startswith('sqlite://'):
            raise ValueError("Database URL must be a valid SQLite connection string")
        return values

    @root_validator(pre=True)
    def validate_database_name(cls, values):
        if not values['database_name'].isalnum():
            raise ValueError("Database name must be alphanumeric")
        return values

# Load the configuration file
with open('config.json', 'r') as f:
    config_data = json.load(f)

try:
    # Attempt to validate the configuration
    config = Config(**config_data)
except ValidationError as e:
    # Print the error messages
    for error in e.errors():
        print(f"Error: {error['loc'][0]} - {error['msg']}")
else:
    # Print the validated configuration
    print("Validated Configuration:")
    print(config)
