from datetime import datetime

def parse_iso8601_string(date_string, date_format="%Y-%m-%d", time_format="%H:%M:%S", 
                         day_first=True, yearfirst=True):
    try:
        if date_first and day_first:
            return datetime.strptime(date_string, f"{date_format} {time_format}")
        elif date_first:
            return datetime.strptime(date_string, f"{date_format} {time_format}")
        elif day_first:
            return datetime.strptime(date_string, f"{time_format} {date_format}")
        elif yearfirst:
            return datetime.strptime(date_string, f"{year_format} {date_format} {time_format}")
        else:
            return datetime.strptime(date_string, f"{date_format} {time_format}")
    except ValueError:
        raise ValueError("Invalid ISO 8601 string")

# Example usage
date_string = "2022-07-25T16:30:00"
date_object = parse_iso8601_string(date_string)
print(date_object)

date_string = "2022-07-25T16:30:00"
date_object = parse_iso8601_string(date_string, day_first=True)
print(date_object)

date_string = "2022-07-25T16:30:00"
date_object = parse_iso8601_string(date_string, yearfirst=True)
print(date_object)

date_string = "2022-07-25T16:30:00"
date_object = parse_iso8601_string(date_string, date_format="%d-%m-%Y", time_format="%H:%M:%S")
print(date_object)
