from fastapi import FastAPI
from fastapi.responses import JSONResponse
from fastapi.requests import Request
from pydantic import BaseModel
from sqlalchemy import create_engine
from sqlalchemy.orm import sessionmaker
from alembic import config, migration
from alembic import api

app = FastAPI()

# Initialize SQLAlchemy database
engine = create_engine('postgresql://user:password@localhost/dbname')
SessionLocal = sessionmaker(bind=engine)

# Initialize Alembic migration
base_config = config.Config("alembic.ini")
base_config.set_main_option("sqlalchemy.url", engine.url)
base_config.set_main_option("sqlalchemy.url", engine.url)
with api.compare_revision("head", base_config) as compare:
    compare.create_head()
    compare.create_revision()

class User(BaseModel):
    id: int
    name: str
    email: str

@app.get("/users/")
def read_users():
    db = SessionLocal()
    try:
        users = db.query(User).all()
        return JSONResponse(content={"users": [user.dict() for user in users]}, status_code=200)
    finally:
        db.close()

@app.post("/users/")
def create_user(user: User):
    db = SessionLocal()
    try:
        db.add(user)
        db.commit()
        db.refresh(user)
        return JSONResponse(content={"user": user.dict()}, status_code=201)
    finally:
        db.close()

@app.put("/users/{user_id}")
def update_user(user_id: int, user: User):
    db = SessionLocal()
    try:
        existing_user = db.query(User).get(user_id)
        if existing_user:
            existing_user.name = user.name
            existing_user.email = user.email
            db.commit()
            return JSONResponse(content={"user": existing_user.dict()}, status_code=200)
        else:
            return JSONResponse(content={"error": "User not found"}, status_code=404)
    finally:
        db.close()

@app.delete("/users/{user_id}")
def delete_user(user_id: int):
    db = SessionLocal()
    try:
        existing_user = db.query(User).get(user_id)
        if existing_user:
            db.delete(existing_user)
            db.commit()
            return JSONResponse(content={"message": "User deleted"}, status_code=200)
        else:
            return JSONResponse(content={"error": "User not found"}, status_code=404)
    finally:
        db.close()
