import threading

class Lock:
    def __init__(self):
        self._locked = False
        self._queue = threading.Condition(threading.Lock())

    def acquire(self):
        while self._locked:
            self._queue.wait()
        self._locked = True

    def release(self):
        self._locked = False
        self._queue.notify_all()
