import numpy as np
from farmhash import farmhash32, farmhash64

class FarmhashTable:
    def __init__(self, hash_type='32', size=1000):
        self.size = size
        if hash_type == '32':
            self.hash = farmhash32(self.size)
        elif hash_type == '64':
            self.hash = farmhash64(self.size)
        else:
            raise ValueError("Invalid hash type. Supported types are '32' and '64'.")

    def add(self, key):
        if len(self) < self.size:
            self.hash[key] = None
        else:
            # Handle collision using open addressing
            index = hash(key) % self.size
            while self.hash[index] is not None:
                index = (index + 1) % self.size
            self.hash[index] = key

    def remove(self, key):
        if key in self.hash:
            index = hash(key) % self.size
            while self.hash[index] is not None:
                if self.hash[index] == key:
                    del self.hash[index]
                    break
                index = (index + 1) % self.size
        else:
            raise KeyError(f"{key} not found in the hash table.")

    def __iter__(self):
        return iter(self.hash)

    def __len__(self):
        return len(self.hash)

# Example usage:
table = FarmhashTable('64')
table.add(1)
table.add(2)
for key in table:
    print(key)
