    def get_commits_with_tree(self, repo, tree):
        return self.repo.get_commits_with_tree(repo, tree)

    def get_commits_with_tree_and_parents(self, repo, tree, parents):
        return self.repo.get_commits_with_tree_and_parents(repo, tree, parents)

    def get_commit(self, commit_hash):
        return self.repo.get_commit(commit_hash)

    def get_tree(self, commit_hash):
        return self.repo.get_tree(commit_hash)

    def get_tree_with_parents(self, commit_hash, parents):
        return self.repo.get_tree_with_parents(commit_hash, parents)

    def get_ref(self, ref):
        return self.repo.get_ref(ref)

    def get_ref_with_parents(self, ref, parents):
        return self.repo.get_ref_with_parents(ref, parents)

    def push(self, refs):
        self.repo.push(refs)

    def pull(self, refs):
