```python
import asyncio
import socket
import struct

# HTTP/2 frame types
FRAME_TYPES = {
    b'\x00': 'CONNECT',
    b'\x01': 'CONTINUATION',
    b'\x02': 'HEADERS',
    b'\x03': 'PAYLOAD',
    b'\x04': 'PUSH_PROMISE',
    b'\x05': 'UNORDERED_CONTENT',
    b'\x06': 'HANDSHAKE',
    b'\x07': 'PROTOCOL_ERROR',
    b'\x08': 'SYNSET',
    b'\x09': 'ACK',
    b'\x0a': 'WINDOW_UPDATE',
    b'\x0b': 'END_STREAM'
}

class HTTP2Stream:
    def __init__(self, connection):
        self.connection = connection
        self.state = 'INIT'
        self.stream_id = None
        self.stream_flags = {}
        self.header_frame = None
        self.payload_frames = []
        self.push Promises = []

    async def handle_frame(self, frame):
        if self.state == 'INIT':
            if frame.type == b'\x01' and frame.stream_id == 0:
                self.state = 'ESTABLISHING'
            elif frame.type == b'\x06':
                self.state = 'HANDSHAKE'
            else:
                raise ValueError('Invalid frame type')

        elif self.state == 'ESTABLISHING':
            if frame.type == b'\x01' and frame.stream_id == self.stream_id:
                self.state = 'ESTABLISHED'
            elif frame.type == b'\x02' and frame.stream_id == self.stream_id:
                self.state = 'ESTABLISHED'
            elif frame.type == b'\x07' and frame.stream_id == 0:
                self.state = 'CLOSED'

        elif self.state == 'ESTABLISHED':
            if frame.type == b'\x02':
                self.header_frame = frame
            elif frame.type == b'\x03':
                self.payload_frames.append(frame)
            elif frame.type == b'\x04':
                self.push Promises.append(frame)
            elif frame.type == b'\x05':
                self.push Promises.append(frame)
            elif frame.type == b'\x0a':
                if 'max_stream_size' in self.stream_flags:
                    self.connection.max_stream_size = self.stream_flags['max_stream_size']
            elif frame.type == b'\x0b':
                self.stream_flags['max_stream_size'] = frame.stream_id
            elif frame.type == b'\x0b' and frame.stream_id == self.stream_id:
                self.state = 'CLOSED'
            elif frame.type == b'\x0b' and frame.stream_id == 0:
                self.state = 'CLOSED'

            elif frame.type == b'\x09':
                if frame.stream_id == self.stream_id:
                    self.state = 'CLOSED'

        elif self.state == 'CLOSED':
            if frame.type == b'\x08':
                self.state = 'CLOSED'

class HTTP2Connection:
    def __init__(self, host, port):
        self.host = host
        self.port = port
        self.max_stream_size = None
        self.streams = {}
        self.server_socket = None

    async def establish_connection(self):
        self.server_socket = await asyncio.start_server(self.handle_client, self.host, self.port)

    async def handle_client(self, reader, writer):
        self.streams[writer.get_extra_info('remote_address')] = HTTP2Stream(writer)
        await self.handle_client_loop(reader, writer)

    async def handle_client_loop(self, reader, writer):
        while True:
            frame = await asyncio.to_thread(socket.recv, writer.fileno(), 1024)
            await self.streams[writer.get_extra_info('remote_address')].handle_frame(frame)
            if self.streams[writer.get_extra_info('remote_address')].state == 'CLOSED':
                writer.close()
                break

async def main():
    connection = HTTP2Connection('localhost', 8000)
    await connection.establish_connection()
    await asyncio.Future()  # run forever

asyncio.run(main())
```

```python
from collections import OrderedDict

class OrderedSet:
    def __init__(self):
        self.ordered_set = OrderedDict()

    def add(self, element):
        self.ordered_set[element] = None

    def discard(self, element):
        if element in self.ordered_set:
            del self.ordered_set[element]

    def clear(self):
        self.ordered_set.clear()

    def union(self, other):
        if isinstance(other, OrderedSet):
            new_set = OrderedSet()
            for key in self.ordered_set.keys():
                new_set.add(key)
            for key in other.ordered_set.keys():
                new_set.add(key)
            return new_set
        else:
            new_set = OrderedSet()
            for key in self.ordered_set.keys():
                new_set.add(key)
            return new_set

    def intersection(self, other):
        if isinstance(other, OrderedSet):
            new_set = OrderedSet()
            for key in self.ordered_set.keys():
                if key in other.ordered_set.keys():
                    new_set.add(key)
            return new_set
        else:
            new_set = OrderedSet()
            for key in self.ordered_set.keys():
                if key in other:
                    new_set.add(key)
            return new_set

    def difference(self, other):
        if isinstance(other, OrderedSet):
            new_set = OrderedSet()
            for key in self.ordered_set.keys():
                if key not in other.ordered_set.keys():
                    new_set.add(key)
            return new_set
        else:
            new_set = OrderedSet()
            for key in self.ordered_set.keys():
                if key not in other:
                    new_set.add(key)
            return new_set

    def symmetric_difference(self, other):
        if isinstance(other, OrderedSet):
            new_set = OrderedSet()
            for key in self.ordered_set.keys():
                if key not in other.ordered_set.keys():
                    new_set.add(key)
            for key in other.ordered_set.keys():
                if key not in self.ordered_set.keys():
                    new_set.add(key)
            return new_set
        else:
            new_set = OrderedSet()
            for key in self.ordered_set.keys():
                if key not in other:
                    new_set.add(key)
            for key in other.keys():
                if key not in self.ordered_set.keys():
                    new_set.add(key)
            return new_set

    def __iter__(self):
        return iter(self.ordered_set.keys())

    def __len__(self):
        return len(self.ordered_set)
