import re
from packaging import version

class SemVer:
    def __init__(self, version_str):
        self.version_str = version_str

    @classmethod
    def parse(cls, version_str):
        return cls(version_str)

    @property
    def major(self):
        return int(self.version_str.split('.')[0])

    @property
    def minor(self):
        return int(self.version_str.split('.')[1])

    @property
    def patch(self):
        return int(self.version_str.split('.')[2])

    @property
    def pre(self):
        match = re.search(r'\.pre(\d+)', self.version_str)
        if match:
            return int(match.group(1))
        else:
            return None

    @property
    def build(self):
        match = re.search(r'\.(\d+)', self.version_str)
        if match:
            return int(match.group(1))
        else:
            return None

    def validate(self):
        try:
            version.Version(self.version_str)
            return True
        except version.InvalidVersion:
            return False

    @staticmethod
    def compare(a, b):
        a_parts = list(map(int, a.split('.')))
        b_parts = list(map(int, b.split('.')))
        for a_part, b_part in zip(a_parts, b_parts):
            if a_part > b_part:
                return 1
            elif a_part < b_part:
                return -1
        if len(a_parts) < len(b_parts):
            return -1
        elif len(a_parts) > len(b_parts):
            return 1
        return 0

    @staticmethod
    def generate_changelog(current_version, changes):
        changelog = []
        for change in changes:
            changelog.append(f"{current_version} {change['description']}")
        return changelog


# Example usage:
if __name__ == "__main__":
    # Parse a version string
    semver = SemVer.parse("1.2.3")
    print(f"Major: {semver.major}, Minor: {semver.minor}, Patch: {semver.patch}")

    # Validate a version string
    print(semver.validate())

    # Compare two versions
    print(SemVer.compare("1.2.3", "1.2.4"))

    # Generate a changelog
    changes = [
        {"description": "Fixed bug in login feature"},
        {"description": "Added support for new API endpoint"}
    ]
    current_version = "1.2.3"
    print(SemVer.generate_changelog(current_version, changes))
```

