from sentencepiece import SentencePiece

class SentencePieceModel:
    def __init__(self, model_path):
        self.model = SentencePiece.from_file(model_path)

    def tokenize(self, sentence):
        return self.model.encode(sentence)

    def get_sentence_length(self, sentence):
        return len(self.tokenize(sentence))

    def generate(self, input_sentence, max_length=100):
        encoded_sentence = self.tokenize(input_sentence)
        generated_sentence = self.model.generate(encoded_sentence, max_length=max_length)
        return self.model.decode(generated_sentence)
