```python
class Promise:
    def __init__(self, value=None):
        self._value = value
        self._done = False
        self._chain = None
        self._deferred = None

    def then(self, onfulfilled, onrejected):
        self._chain = Chain(self, onfulfilled, onrejected)
        return self._chain

    def catch(self, onrejected):
        return self.then(lambda x: x, onrejected)

    def finally(self, callback):
        def wrapper():
            if self._done:
                callback()
            else:
                self._chain._chain._done = True
                callback()
        return wrapper()

    def done(self, value, reason):
        self._value = value
        self._done = True
        self._deferred = None
        if self._chain:
            self._chain._chain._done = True

    def reject(self, reason):
        self._value = None
        self._done = True
        self._deferred = None
        if self._chain:
            self._chain._chain._done = True

    def inspect(self):
        return {
            'status': 'pending' if not self._done else ('fulfilled' if self._value else 'rejected'),
            'value': self._value,
            'reason': self._value if not self._done else self._value
        }

class Chain:
    def __init__(self, promise, onfulfilled, onrejected):
        self._promise = promise
        self._onfulfilled = onfulfilled
        self._onrejected = onrejected
        self._done = False
        self._chain = None

    def _call_onfulfilled(self, value):
        if self._onfulfilled:
            self._onfulfilled(value)
        self._done = True
        if self._chain:
            self._chain._chain._done = True

    def _call_onrejected(self, reason):
        if self._onrejected:
            self._onrejected(reason)
        self._done = True
        if self._chain:
            self._chain._chain._done = True

    def then(self, onfulfilled, onrejected):
        chain = Chain(self._promise._chain, onfulfilled, onrejected)
        self._chain = chain
        return chain

    def catch(self, onrejected):
        chain = Chain(self._promise._chain, lambda x: None, onrejected)
        self._chain = chain
        return chain

    def inspect(self):
        return {
            'status': 'pending' if not self._done else ('fulfilled' if self._promise._value else 'rejected'),
            'value': self._promise._value,
            'reason': self._promise._value if not self._done else self._promise._value
        }
