class FortniteAPI:
    def __init__(self, username, password):
        self.base_url = "https://api.epicgames.com"
        self.username = username
        self.password = password
        self.access_token = None

    def login(self):
        # Epic Games API Login
        data = {
            "username": self.username,
            "password": self.password
        }
        response = requests.post(f"{self.base_url}/user/login", json=data)
        if response.status_code == 200:
            self.access_token = response.json()["access_token"]
            return True
        return False

    def logout(self):
        # Epic Games API Logout
        if self.access_token:
            response = requests.post(f"{self.base_url}/user/logout", headers={"Authorization": f"Bearer {self.access_token}"})
            if response.status_code == 200:
                self.access_token = None
                return True
        return False

    def get_user_info(self):
        # Epic Games API Get User Info
        if self.access_token:
            response = requests.get(f"{self.base_url}/user/me", headers={"Authorization": f"Bearer {self.access_token}"})
            if response.status_code == 200:
                return response.json()
        return None

    def get_access_token(self):
        # Epic Games API Get Access Token
        response = requests.get(f"{self.base_url}/user/me", headers={"Authorization": "Bearer "})
        if response.status_code == 200:
            return response.json()["access_token"]
        return None
