import requests
import json

class SalesforceAPI:
    def __init__(self, access_token):
        self.access_token = access_token
        self.base_url = "https://login.salesforce.com"

    def get(self, endpoint, params=None):
        headers = {
            "Authorization": f"Bearer {self.access_token}",
            "Content-Type": "application/json"
        }
        response = requests.get(f"{self.base_url}{endpoint}", headers=headers, params=params)
        response.raise_for_status()
        return response.json()

    def post(self, endpoint, data=None, params=None):
        headers = {
            "Authorization": f"Bearer {self.access_token}",
            "Content-Type": "application/json"
        }
        response = requests.post(f"{self.base_url}{endpoint}", headers=headers, json=data, params=params)
        response.raise_for_status()
        return response.json()

    def put(self, endpoint, data=None, params=None):
        headers = {
            "Authorization": f"Bearer {self.access_token}",
            "Content-Type": "application/json"
        }
        response = requests.put(f"{self.base_url}{endpoint}", headers=headers, json=data, params=params)
        response.raise_for_status()
        return response.json()

    def delete(self, endpoint, params=None):
        headers = {
            "Authorization": f"Bearer {self.access_token}",
            "Content-Type": "application/json"
        }
        response = requests.delete(f"{self.base_url}{endpoint}", headers=headers, params=params)
        response.raise_for_status()
        return response.json()

# Example usage:
