import traceback

class TracebackSerializer:
    @staticmethod
    def serialize(traceback_obj):
        """Serializes a traceback object into a string."""
        return repr(traceback_obj)

    @staticmethod
    def deserialize(serialized_str):
        """Deserializes a string back into a traceback object."""
        return eval(serialized_str)

# Example usage
try:
    x = 1 / 0
except ZeroDivisionError:
    tb = traceback.format_exc()
    serialized_tb = TracebackSerializer.serialize(tb)
    print(serialized_tb)

    deserialized_tb = TracebackSerializer.deserialize(serialized_tb)
    print(deserialized_tb)
