from bs4 import BeautifulSoup
from dateparser import parse
import requests

def parse_dates(html):
    soup = BeautifulSoup(html, 'lxml')
    dates = []

    for element in soup.find_all(['p', 'span', 'div']):
        for attr in element.attrs:
            value = element[attr]
            if any(date in value for date in ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']):
                date_str = value.strip()
                if date_str:
                    try:
                        date_obj = parse(date_str)
                        if date_obj:
                            dates.append(date_obj)
                    except Exception as e:
                        print(f"Failed to parse date: {date_str}, error: {str(e)}")

    return dates

def main():
    url = "http://example.com"  # replace with your URL
    response = requests.get(url)
    html = response.text
    dates = parse_dates(html)
    for date in dates:
        print(date)

if __name__ == "__main__":
    main()
