```python
import re
from collections import defaultdict

class CSSParser:
    def __init__(self, file_path):
        self.file_path = file_path
        self.css_rules = defaultdict(dict)

    def parse_css(self):
        with open(self.file_path, 'r') as file:
            css_content = file.read()

        rules = re.findall(r'([^{]+)\s*\{\s*([^}]+)\s*\}', css_content)
        for rule in rules:
            selector, properties = rule
            properties = re.split(r';|:', properties)
            for prop in properties:
                if prop:
                    key, value = prop.split(':', 1)
                    self.css_rules[selector][key.strip()] = value.strip()

    def get_selectors(self):
        return list(self.css_rules.keys())

    def get_properties(self, selector):
        return self.css_rules.get(selector, {})

    def get_property_value(self, selector, property_name):
        return self.css_rules.get(selector, {}).get(property_name)

# Example usage:
parser = CSSParser('path_to_your_css_file.css')
parser.parse_css()
selectors = parser.get_selectors()
print(selectors)

selector = 'your_selector_here'
properties = parser.get_properties(selector)
print(properties)

property_name = 'your_property_name_here'
property_value = parser.get_property_value(selector, property_name)
print(property_value)
