import requests

def get_issues(api_url, token, project_key, issue_type):
    headers = {
        'Authorization': f'Bearer {token}',
        'Content-Type': 'application/json'
    }

    params = {
        'jql': f'issue type = "{issue_type}" AND project = "{project_key}"'
    }

    response = requests.get(api_url + '/rest/api/2/search', headers=headers, params=params)
    return response.json()

def get_issue(api_url, token, issue_id):
    headers = {
        'Authorization': f'Bearer {token}',
        'Content-Type': 'application/json'
    }

    response = requests.get(api_url + '/rest/api/2/issue/{issue_id}'.format(issue_id=issue_id), headers=headers)
    return response.json()

def create_issue(api_url, token, project_key, issue_type, summary, description):
    headers = {
        'Authorization': f'Bearer {token}',
        'Content-Type': 'application/json'
    }

    data = {
        'fields': {
            'summary': summary,
            'description': description,
            'issuetype': {
                'name': issue_type
            }
        }
    }

    response = requests.post(api_url + '/rest/api/2/issue', headers=headers, json=data)
    return response.json()

def update_issue(api_url, token, issue_id, summary, description):
    headers = {
        'Authorization': f'Bearer {token}',
        'Content-Type': 'application/json'
    }

    data = {
        'fields': {
            'summary': summary,
            'description': description
        }
    }

    response = requests.put(api_url + '/rest/api/2/issue/{issue_id}'.format(issue_id=issue_id), headers=headers, json=data)
    return response.json()

def delete_issue(api_url, token, issue_id):
    headers = {
        'Authorization': f'Bearer {token}',
        'Content-Type': 'application/json'
    }

    response = requests.delete(api_url + '/rest/api/2/issue/{issue_id}'.format(issue_id=issue_id), headers=headers)
    return response.json()
