```python
import json
import re

def validate_json_schema(schema, data):
    """
    Validates a JSON object against a given schema.

    Args:
        schema (dict): The JSON schema to validate against.
        data (dict): The JSON data to validate.

    Returns:
        bool: True if the data is valid, False otherwise.
    """
    # Check if the schema is an object
    if not isinstance(schema, dict):
        return False

    # Iterate over each key in the schema
    for key, value in schema.items():
        # Check if the key exists in the data
        if key not in data:
            return False

        # Check if the value is a string and it's a regex pattern
        if isinstance(value, str) and re.match(r'^\/[a-zA-Z]+$', value):
            # If it's a regex pattern, validate the data against it
            if not re.match(value, str(data[key])):
                return False
        # Check if the value is an object and recursively validate it
        elif isinstance(value, dict):
            if not validate_json_schema(value, data[key]):
                return False
        # Check if the value is an array and validate each item in it
        elif isinstance(value, list):
            for item in value:
                if not validate_json_schema(value, item):
                    return False
        # If none of the above conditions are met, the value is a primitive type
        else:
            # If the value is not equal to the data's value, the data is invalid
            if value != data[key]:
                return False

    # If all checks pass, the data is valid
    return True

# Example usage:
schema = {
    "type": "object",
    "properties": {
        "name": {"type": "string"},
        "age": {"type": "integer"}
    },
    "required": ["name", "age"]
}

data = {
    "name": "John",
    "age": 30
}

if validate_json_schema(schema, data):
    print("Data is valid")
else:
    print("Data is invalid")
```

