# cython: boundscheck=False
# cython: wraparound=False
from cython import externfrom
from unordered_map import unordered_map

class CythonHashTable:
    cdef externfrom "unordered_map":
        externfrom "unordered_map" unordered_map

    def __init__(self, size):
        self.size = size
        self.map = unordered_map(size)

    def _hash(self, key):
        return key

    def insert(self, key, value):
        index = self._hash(key) % self.size
        self.map[index].insert(key, value)

    def get(self, key):
        index = self._hash(key) % self.size
        return self.map[index].get(key)

    def remove(self, key):
        index = self._hash(key) % self.size
        self.map[index].remove(key)
