from sqlalchemy import create_engine, text
import random
from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import sessionmaker
from sqlalchemy import func

def create_utility_functions(engine):
    Session = sessionmaker(bind=engine)
    session = Session()

    def generate_random_id():
        return str(random.randint(100000000000000000, 999999999999999999))

    def create_dummy_data(model):
        dummy_data = {}
        for attribute in model.__table__.columns:
            if attribute.type.name != 'String':
                continue
            dummy_data[attribute.name] = str(random.choice(['', 'Male', 'Female']))
        return dummy_data

    def execute_sql_script(script):
        session.execute(text(script))

    def insert_dummy_data(model, num_records):
        for _ in range(num_records):
            data = create_dummy_data(model)
            session.add(model(**data))
        session.commit()

    def get_random_id():
        return session.query(func.random()).first()[0]

    utility_functions = {
        'generate_random_id': generate_random_id,
        'create_dummy_data': create_dummy_data,
        'execute_sql_script': execute_sql_script,
        'insert_dummy_data': insert_dummy_data,
        'get_random_id': get_random_id
    }
    return utility_functions

# Example usage:
engine = create_engine('sqlite:///example.db')
utility_functions = create_utility_functions(engine)
