```python
import multiprocessing
import threading
from queue import Queue

class ProcessManager:
    def __init__(self):
        self._processes = []
        self._threads = []
        self._queues = {}

    def spawn_process(self, func, args=()):
        process = multiprocessing.Process(target=func, args=args)
        self._processes.append(process)
        process.start()
        return process

    def spawn_thread(self, func, args=()):
        thread = threading.Thread(target=func, args=args)
        self._threads.append(thread)
        thread.start()
        return thread

    def sync_process(self, process, queue):
        while True:
            item = queue.get()
            if item is None:
                break
            process.apply(item)
            queue.task_done()

    def sync_thread(self, thread, queue):
        while True:
            item = queue.get()
            if item is None:
                break
            thread.apply(item)
            queue.task_done()

    def join_processes(self):
        for process in self._processes:
            process.join()

    def join_threads(self):
        for thread in self._threads:
            thread.join()

    def close(self):
        for process in self._processes:
            process.terminate()
        for thread in self._threads:
            thread.join()

class QueueManager:
    def __init__(self):
        self._queue = Queue()

    def put(self, item):
        self._queue.put(item)

    def get(self):
        return self._queue.get()

    def empty(self):
        return self._queue.empty()

    def full(self):
        return self._queue.full()

    def join(self):
        self._queue.join()

def worker(num):
    print(f"Worker {num} started")
    for i in range(5):
        print(f"Worker {num}: {i}")
    print(f"Worker {num} finished")

def main():
    manager = ProcessManager()
    queue_manager = QueueManager()

    process = manager.spawn_process(worker, args=(1,))
    thread = manager.spawn_thread(worker, args=(2,))

    manager.sync_process(process, queue_manager._queue)
    manager.sync_thread(thread, queue_manager._queue)

    for i in range(10):
        queue_manager.put(i)
        print(f"Put {i}")

    manager.join_processes()
    manager.join_threads()
    print("All processes and threads finished")

if __name__ == "__main__":
    main()
```

```python
class ExceptionGroup:
    def __init__(self, *exceptions):
        self.exceptions = exceptions

    def __repr__(self):
        return f"ExceptionGroup({self.exceptions})"

    def __str__(self):
        return f"ExceptionGroup({', '.join(str(e) for e in self.exceptions)})"

    def __or__(self, other):
        if not isinstance(other, ExceptionGroup):
            return other
        return ExceptionGroup(*self.exceptions, *other.exceptions)

    def __or__(self, exc):
        if not isinstance(exc, Exception):
            return self
        return ExceptionGroup(*self.exceptions, exc)

    def __iter__(self):
        return iter(self.exceptions)

    def __len__(self):
        return len(self.exceptions)

    def __contains__(self, exc):
        return exc in self.exceptions

    def __bool__(self):
        return any(self.exceptions)

def raise_exception_group(*exceptions):
    return ExceptionGroup(*exceptions)

# Example usage:
try:
    # Simulate some error
    raise ExceptionGroup(FileNotFoundError, PermissionError)
except ExceptionGroup as e:
    print(f"Caught exception group: {e}")
    for exc in e:
        print(f"Caught exception: {exc}")
