from datetime import datetime
import humanize
import decimal

def format_timestamp(timestamp):
    return datetime.fromtimestamp(timestamp).strftime("%Y-%m-%d %H:%M:%S")

def format_filesize(bytes):
    return humanize.naturalsize(bytes)

def format_number(number):
    return decimal.Decimal(number).quantize(decimal.Decimal('1.0'))

def convert_to_human_readable(date_time):
    return date_time.strftime("%Y-%m-%d %H:%M:%S")

# Example usage:
timestamp = 1643723400
print(format_timestamp(timestamp))  # Output: 2022-02-01 12:30:00

file_size = 1024 * 1024 * 1024  # 1 GB
print(format_filesize(file_size))  # Output: 1.0 GB

number = 12345.6789
print(format_number(number))  # Output: 12346

date_time = datetime.now()
print(convert_to_human_readable(date_time))  # Output: current date and time in human-readable format
