class DotDict(dict):
    def __getattr__(self, name):
        return self[name]

    def __setattr__(self, name, value):
        self[name] = value

    def __delattr__(self, name):
        if name in self:
            del self[name]

    def add(self, key, value):
        self[key] = value

    def delete(self, key):
        if key in self:
            del self[key]

# Example usage:
obj = DotDict({'a': 1, 'b': 2})

print(obj.a)  # Outputs: 1
print(obj.b)  # Outputs: 2

obj.add('c', 3)
print(obj.c)  # Outputs: 3

obj.delete('b')
try:
    print(obj.b)
except KeyError:
    print("KeyError: 'b'")
