class ConsolePrinter:
    def __init__(self):
        self.colors = {
            'green': '\033[92m',
            'red': '\033[91m',
            'yellow': '\033[93m',
            'blue': '\033[94m',
            'magenta': '\033[95m',
            'cyan': '\033[96m',
            'end': '\033[0m'
        }

    def print(self, message, color=None):
        if color:
            print(self.colors[color] + message + self.colors['end'], end=' ')
        else:
            print(message, end=' ')

    def print_colored(self, message, color):
        print(self.colors[color] + message + self.colors['end'], end=' ')

    def print_error(self, message):
        self.print(message, color='red')

    def print_success(self, message):
        self.print(message, color='green')

    def print_info(self, message):
        self.print(message, color='blue')

    def print_warning(self, message):
        self.print(message, color='yellow')

    def print_cyan(self, message):
        self.print(message, color='cyan')

    def print_magenta(self, message):
        self.print(message, color='magenta')


def main():
    printer = ConsolePrinter()

    while True:
        print("Console Printer")
        print("1. Print message")
        print("2. Print colored message")
        print("3. Print error")
        print("4. Print success")
        print("5. Print info")
        print("6. Print warning")
        print("7. Print cyan message")
        print("8. Print magenta message")
        print("9. Exit")

        choice = input("Enter your choice: ")

        if choice == '1':
            message = input("Enter your message: ")
            printer.print(message)
        elif choice == '2':
            message = input("Enter your message: ")
            color = input("Enter color (green, red, yellow, blue, magenta, cyan): ")
            printer.print_colored(message, color)
        elif choice == '3':
            message = input("Enter your error message: ")
            printer.print_error(message)
        elif choice == '4':
            message = input("Enter your success message: ")
            printer.print_success(message)
        elif choice == '5':
            message = input("Enter your info message: ")
            printer.print_info(message)
        elif choice == '6':
            message = input("Enter your warning message: ")
            printer.print_warning(message)
        elif choice == '7':
            message = input("Enter your cyan message: ")
            printer.print_cyan(message)
        elif choice == '8':
            message = input("Enter your magenta message: ")
            printer.print_magenta(message)
        elif choice == '9':
            break
        else:
            print("Invalid choice. Please try again.")


if __name__ == "__main__":
    main()
