import json

def load_json_file(filename):
    try:
        with open(filename, 'r') as file:
            return json.load(file)
    except FileNotFoundError:
        print(f"File {filename} not found.")
        return None
    except json.JSONDecodeError as e:
        print(f"Error parsing file {filename}: {e}")
        return None

def compare_json_files(file1, file2):
    data1 = load_json_file(file1)
    data2 = load_json_file(file2)

    if data1 is None or data2 is None:
        return

    if set(data1.keys()) != set(data2.keys()):
        print("Differences in keys:")
        for key in set(data1.keys()) ^ set(data2.keys()):
            print(f"- {key}: {data1.get(key)} (in {file1})")
            print(f"- {key}: {data2.get(key)} (in {file2})")
    else:
        for key in data1.keys():
            if data1[key] != data2[key]:
                print(f"Difference in key '{key}':")
                print(f"- {file1}: {data1[key]}")
                print(f"- {file2}: {data2[key]}")

# Example usage
compare_json_files('file1.json', 'file2.json')
