import os

class Path:
    def __init__(self, path):
        self.path = path

    def join(self, *parts):
        return os.path.join(self.path, *parts)

    def separate(self):
        return os.pathsep.join(self.path.split(os.path.sep))

    def normalize(self):
        return os.path.normpath(self.path)

    def __str__(self):
        return os.path.normpath(self.path)


# Example usage:
path = Path("/home/user/documents")
print(path.join("file.txt"))  # Output: /home/user/documents/file.txt
print(path.separate())  # Output: /home/user/documents/file.txt
print(path.normalize())  # Output: /home/user/documents/file.txt
print(path)  # Output: /home/user/documents/file.txt
