# signals.py

from django.db.models.signals import pre_save
from django.dispatch import receiver
from django.utils.translation import gettext_lazy as _

@receiver(pre_save)
def dynamic_filter_pre_save(sender, instance, **kwargs):
    # Get the model instance and its fields
    model_instance = instance
    model_fields = [field.name for field in model_instance._meta.fields]

    # Create a dictionary to store the filter options
    filter_options = {}

    # Iterate over each field and add it to the filter options dictionary
    for field in model_fields:
        if hasattr(model_instance, f'get_{field}'):
            filter_options[field] = getattr(model_instance, f'get_{field}')(instance)

    # Save the filter options to the instance
    setattr(instance, 'filter_options', filter_options)
```

