# views.py

from django.shortcuts import render, redirect
from .forms import ModelFilterForm
from .models import Model

def model_list(request):
    model_instance = Model.objects.all()
    return render(request, 'model_list.html', {'model_instance': model_instance})

def model_detail(request, pk):
    model_instance = Model.objects.get(pk=pk)
    return render(request, 'model_detail.html', {'model_instance': model_instance})

def model_filter(request):
    if request.method == 'POST':
        form = ModelFilterForm(request.POST)
        if form.is_valid():
            filter_options = form.cleaned_data['filter_options']
            model_instance = Model.objects.all()
            for field, value in filter_options.items():
                model_instance = model_instance.filter(**{field: value})
            return redirect('model_list', pk=model_instance.pk)
    else:
        form = ModelFilterForm()
    return render(request, 'model_filter.html', {'form': form, 'model_instance': Model.objects.all()})
