import http.server
import socketserver
import graphql
import json

class GraphQLServer(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == '/graphql':
            content_type = self.send_header('Content-type', 'application/json')
            content_type['Content-type'] = 'application/json'
            return self.end_headers(), json.dumps({'message': 'Hello, World!'})

    def do_POST(self):
        if self.path == '/graphql':
            content_length = int(self.headers['Content-Length'])
            body = self.rfile.read(content_length)
            try:
                data = json.loads(body.decode('utf-8'))
                result = graphql.GraphQLServer().query(data['query'], data['variables'])
                return self.end_headers(), json.dumps({'data': result})
            except Exception as e:
                return self.end_headers(), json.dumps({'error': str(e)})

class GraphQLServerHandler(socketserver.TCPServer):
    def serve_forever(self):
        print('GraphQL Server is running on port 8080...')
        httpd = socketserver.TCPServer(('localhost', 8080), GraphQLServer)
        httpd.serve_forever()

if __name__ == "__main__":
    handler = GraphQLServerHandler(('localhost', 8080))
    handler.serve_forever()
```

