import importlib_resources
import importlib_metadata

def lazy_import(name):
    try:
        spec = importlib_metadata.specifier(name)
        if spec.isdir():
            return importlib_resources.contents(spec)
        else:
            return importlib_resources.files(spec).open()
    except importlib_metadata.Invalid specifier:
        return None

# Example usage:
module_name = "package.module_name"
contents = lazy_import(module_name)

if contents:
    for item in contents:
        print(item)
else:
    print(f"Failed to import {module_name}")
