from azure.storage.filedatalake import FileDataLakeServiceClient

class AzureDataLakeClient:
    def __init__(self, account_url, file_system_name, account_key):
        self.account_url = account_url
        self.file_system_name = file_system_name
        self.account_key = account_key
        self.client = FileDataLakeServiceClient(account_url, account_key)

    def create_directory(self, directory_path):
        try:
            self.client.create_directory(directory_path)
            print(f"Directory {directory_path} created successfully.")
        except Exception as e:
            print(f"Failed to create directory {directory_path}: {str(e)}")

    def delete_directory(self, directory_path):
        try:
            self.client.delete_directory(directory_path)
            print(f"Directory {directory_path} deleted successfully.")
        except Exception as e:
            print(f"Failed to delete directory {directory_path}: {str(e)}")

    def list_directories(self, directory_path):
        try:
            directories = self.client.list_directories(directory_path)
            print(f"Directories in {directory_path}: {directories}")
        except Exception as e:
            print(f"Failed to list directories in {directory_path}: {str(e)}")

    def set_permissions(self, directory_path, permissions):
        try:
            self.client.set_permissions(directory_path, permissions)
            print(f"Permissions set for {directory_path} successfully.")
        except Exception as e:
            print(f"Failed to set permissions for {directory_path}: {str(e)}")

    def get_file_system_metadata(self, directory_path):
        try:
            metadata = self.client.get_file_system_metadata(directory_path)
            print(f"File system metadata for {directory_path}: {metadata}")
        except Exception as e:
            print(f"Failed to get file system metadata for {directory_path}: {str(e)}")

# Usage example
if __name__ == "__main__":
    account_url = "https://your_account_name.datalakestore.azure.com/"
    file_system_name = "your_file_system_name"
    account_key = "your_account_key"

    client = AzureDataLakeClient(account_url, file_system_name, account_key)

    # Create a directory
    client.create_directory("/mnt/your_directory_path")

    # Delete a directory
    client.delete_directory("/mnt/your_directory_path")

    # List directories in a directory
    client.list_directories("/mnt/your_directory_path")

    # Set permissions for a directory
    client.set_permissions("/mnt/your_directory_path", "rwxr-xr-x")

    # Get file system metadata for a directory
    client.get_file_system_metadata("/mnt/your_directory_path")
