import yaml
import re

def validate_yaml(file_path):
    try:
        with open(file_path, 'r') as file:
            yaml_data = yaml.safe_load(file)
            if yaml_data is None:
                raise yaml.YAMLError("Failed to parse YAML data")
    except yaml.YAMLError as e:
        print(f"Error parsing YAML file: {e}")
        return False

    # Define rules for valid indentation and keys
    indent_rules = {
        '---': r'^- \t.*$',
        '---\n': r'^- \t.*$',
        '  ...': r'^  \t.*$',
    }

    # Check for valid indentation
    for key, pattern in indent_rules.items():
        if re.search(pattern, file_path):
            return False

    # Check for valid keys
    keys = set()
    with open(file_path, 'r') as file:
        lines = file.readlines()
        for line in lines:
            if line.strip().startswith('- '):
                key = line.strip().lstrip('- ').strip()
                if not re.match(r'^[a-zA-Z_][a-zA-Z_0-9]*$', key):
                    return False
                keys.add(key)

    # Check for duplicate keys
    if len(keys) != len(set(line.strip().lstrip('- ').strip() for line in lines if line.strip().startswith('- '))):
        return False

    return True

# Example usage
file_path = 'example.yaml'
if not validate_yaml(file_path):
    exit(1)
