# Importing necessary libraries
from azure.data lake analytics import AnalyticsClient
from azure.data lake analytics.models import DataLakeStorageAccount, ComputePolicy, JobSubmissionArguments, JobSubmissionOptions
from azure.core.exceptions import HttpResponseError

# Connecting to the Azure Data Lake Analytics account
ADLA_CLIENT = AnalyticsClient(
    account_url="https://<account_name>.dfs.core.windows.net/",
    credentials="<account_key>"
)

# Creating a data lake
def create_data_lake(account_name, container_name, storage_account):
    try:
        data_lake_storage_account = DataLakeStorageAccount(
            name=container_name,
            account=storage_account,
            file_system_name=account_name
        )
        ADLA_CLIENT.data_lakes.create_or_update(data_lake_storage_account)
        print(f"Data lake '{container_name}' created successfully.")
    except HttpResponseError as e:
        print(f"Error creating data lake: {e.status_code}, {e.error_message}")

# Deleting a data lake
def delete_data_lake(account_name, container_name):
    try:
        ADLA_CLIENT.data_lakes.delete_by_name(container_name)
        print(f"Data lake '{container_name}' deleted successfully.")
    except HttpResponseError as e:
        print(f"Error deleting data lake: {e.status_code}, {e.error_message}")

# Creating a compute policy
def create_compute_policy(policy_name, policy_definition):
    try:
        compute_policy = ComputePolicy(
            name=policy_name,
            policy_definition=policy_definition
        )
        ADLA_CLIENT.compute_policies.create_or_update(compute_policy)
        print(f"Compute policy '{policy_name}' created successfully.")
    except HttpResponseError as e:
        print(f"Error creating compute policy: {e.status_code}, {e.error_message}")

# Deleting a compute policy
def delete_compute_policy(policy_name):
    try:
        ADLA_CLIENT.compute_policies.delete_by_name(policy_name)
        print(f"Compute policy '{policy_name}' deleted successfully.")
    except HttpResponseError as e:
        print(f"Error deleting compute policy: {e.status_code}, {e.error_message}")

# Submitting a job
def submit_job(job_name, job_body):
    try:
        job_submission_arguments = JobSubmissionArguments(
            job_name=job_name,
            body=job_body
        )
        job_submission_options = JobSubmissionOptions(
            max_workers=1,
            timeout=600  # 10 minutes
        )
        ADLA_CLIENT.jobs.submit(job_submission_arguments, job_submission_options)
        print(f"Job '{job_name}' submitted successfully.")
    except HttpResponseError as e:
        print(f"Error submitting job: {e.status_code}, {e.error_message}")

# Monitoring a job
def get_job_status(job_name):
    try:
        job = ADLA_CLIENT.jobs.get(job_name)
        print(f"Job '{job_name}' status: {job.status}")
    except HttpResponseError as e:
        print(f"Error getting job status: {e.status_code}, {e.error_message}")
