import inspect

def my_function(a, b):
    if not isinstance(a, (int, float)) or not isinstance(b, (int, float)):
        raise TypeError("Both arguments must be numbers")
    return a + b

def my_function_with_exception(a, b):
    if not isinstance(a, (int, float)) or not isinstance(b, (int, float)):
        raise TypeError("Both arguments must be numbers")
    return a / b

def my_function_with_input(a, b):
    if not isinstance(a, (int, float)) or not isinstance(b, (int, float)):
        raise TypeError("Both arguments must be numbers")
    return a + b

def main():
    # Test the functions
    print("Testing my_function")
    try:
        result = my_function(10, 5)
        print(f"Result: {result}")
    except Exception as e:
        print(f"Exception: {e}")

    print("\nTesting my_function_with_exception")
    try:
        result = my_function_with_exception(10, 0)
        print(f"Result: {result}")
    except Exception as e:
        print(f"Exception: {e}")

    print("\nTesting my_function_with_input")
    try:
        result = my_function_with_input(10, 5)
        print(f"Result: {result}")
    except Exception as e:
        print(f"Exception: {e}")

    # Capture the outcome of function calls using inspect
    frame = inspect.currentframe().f_back
    print("\nCaptured Frame:")
    print(f"Function: {frame.f_code.co_name}")
    print(f"Arguments: {frame.f_code.co_varnames}")
    print(f"Locals: {frame.f_locals}")

if __name__ == "__main__":
    main()
