import json
from dataclasses import dataclass
from datetime import datetime
import numpy as np

@dataclass
class JsonObject:
    """A class representing a JSON object."""
    data: dict

    def to_dict(self):
        """Convert the object to a dictionary."""
        return self.data

    @classmethod
    def from_dict(cls, data: dict):
        """Create a new instance from a dictionary."""
        return cls(data)

@dataclass
class JsonArray:
    """A class representing a JSON array."""
    data: list

    def to_list(self):
        """Convert the array to a list."""
        return self.data

    @classmethod
    def from_list(cls, data: list):
        """Create a new instance from a list."""
        return cls(data)

@dataclass
class JsonValue:
    """A class representing a JSON value."""
    data: any

    def to_dict(self):
        """Convert the value to a dictionary."""
        if isinstance(self.data, datetime):
            return self.data.isoformat()
        elif isinstance(self.data, np.ndarray):
            return self.data.tolist()
        else:
            return self.data

    @classmethod
    def from_dict(cls, data: dict):
        """Create a new instance from a dictionary."""
        if 'timestamp' in data:
            return cls(datetime.fromisoformat(data['timestamp']))
        elif 'array' in data:
            return cls(np.array(data['array']))
        else:
            return cls(data)

def json_encode(obj: JsonValue) -> str:
    """Encode a JSON value to a string."""
    return json.dumps(obj.to_dict())

def json_decode(json_str: str) -> JsonValue:
    """Decode a JSON string to a value."""
    return JsonValue.from_dict(json.loads(json_str))
