from collections import OrderedDict, defaultdict
import functools

def sort_list(input_list):
    """Sorts a list in ascending order."""
    return sorted(input_list)

def sort_list_reverse(input_list):
    """Sorts a list in descending order."""
    return sorted(input_list, reverse=True)

def sort_list_by_key(input_list, key=None):
    """Sorts a list based on a given key."""
    return sorted(input_list, key=key)

def sort_list_stable(input_list):
    """Sorts a list in stable order."""
    return sorted(input_list)

def sort_tuple(input_tuple):
    """Sorts a tuple in ascending order."""
    return tuple(sorted(input_tuple))

def sort_dict(input_dict):
    """Sorts a dictionary by keys."""
    return dict(sorted(input_dict.items()))

def sort_dict_by_key(input_dict, key=None):
    """Sorts a dictionary based on a given key."""
    return dict(sorted(input_dict.items(), key=lambda item: item[1][key]))

def sort_dict_by_value(input_dict):
    """Sorts a dictionary by values."""
    return dict(sorted(input_dict.items(), key=lambda item: item[1]))

def sort_dict_reverse(input_dict):
    """Sorts a dictionary in descending order."""
    return dict(sorted(input_dict.items(), reverse=True))
