```python
class TemplateRenderer:
    def __init__(self):
        self.cache = {}
        self.partials_cache = {}

    def render(self, template, data):
        # Handle partials
        partials = self.parse_partials(template)
        for partial in partials:
            partial_data = self.get_partial_data(partial)
            if partial_data:
                template = template.replace(partial, partial_data)

        # Handle conditionals
        conditionals = self.parse_conditionals(template)
        for conditional in conditionals:
            condition, body = conditional
            if self.evaluate_condition(condition, data):
                template = self.render_template(template, body, data)

        # Handle loops
        loops = self.parse_loops(template)
        for loop in loops:
            loop_var, loop_body = loop
            template = self.render_loop(template, loop_var, loop_body, data)

        # Render the template
        return self.evaluate_template(template, data)

    def parse_partials(self, template):
        partials = []
        start = 0
        while start < len(template):
            end = template.find('{{ partial ', start)
            if end == -1:
                break
            partial_name = template[start + 10:end]
            partials.append(partial_name)
            start = end + 1
        return partials

    def get_partial_data(self, partial_name):
        partial = self.partials_cache.get(partial_name)
        if partial:
            return partial

        with open(f"partials/{partial_name}.html", "r") as f:
            partial = f.read()
            self.partials_cache[partial_name] = partial
            return partial

    def parse_conditionals(self, template):
        conditionals = []
        start = 0
        while start < len(template):
            end = template.find('{{ if ', start)
            if end == -1:
                break
            condition = template[start + 4:end]
            start = end + 1
            end = template.find('}}', start)
            body = template[start:end]
            conditionals.append((condition, body))
            start = end + 2
        return conditionals

    def evaluate_condition(self, condition, data):
        # Evaluate the condition using a simple expression parser
        # This is a very basic implementation and may not cover all cases
        return eval(condition, data)

    def parse_loops(self, template):
        loops = []
        start = 0
        while start < len(template):
            end = template.find('{{ for ', start)
            if end == -1:
                break
            loop_var = template[start + 6:end]
            start = end + 1
            end = template.find('}}', start)
            loop_body = template[start:end]
            loops.append((loop_var, loop_body))
            start = end + 2
        return loops

    def render_loop(self, template, loop_var, loop_body, data):
        # Render the loop body
        loop_body = self.render_template(loop_body, data)
        # Replace the loop variable in the template
        template = template.replace(loop_var, loop_body)
        return template

    def evaluate_template(self, template, data):
        # Evaluate the template using a simple expression parser
        # This is a very basic implementation and may not cover all cases
        return template

# Example usage:
renderer = TemplateRenderer()
template = "<html>{{ title }}<body>{{ message }}</body></html>"
data = {"title": "Hello World", "message": "This is a test"}
print(renderer.render(template, data))
```

