        self.set_port(self.config['port'])
        for lang, modules in self.config['modules'].items():
            for module_name, module in modules.items():
                self.load_module(lang, module_name, module)

    def run(self):
        self.log('running server...')
        self.start()

class MyMiddleware(Middleware):
