```python
import argparse
import os

class ConfigParserArgumentParser(argparse.ArgumentParser):
    def __init__(self):
        super().__init__()
        self.add_argument_group('config')
        self.add_argument('--config-file', type=str, help='Path to config file')

    def parse_args(self):
        args = super().parse_args()
        if args.config_file:
            self.parse_config_file(args.config_file)
        return args

    def parse_config_file(self, config_file):
        if not os.path.exists(config_file):
            raise ValueError(f'Config file {config_file} does not exist')

        with open(config_file, 'r') as f:
            config = {}
            for line in f:
                key, value = line.strip().split('=')
                config[key] = value

        for key, value in config.items():
            self.add_argument(f'--{key}', type=str, help=f'Value for {key}')

def main():
    parser = ConfigParserArgumentParser()
    args = parser.parse_args()
    print(f'Config values: {args.__dict__}')

if __name__ == '__main__':
    main()
