import boto3
import os
import sys

# Set up AWS credentials
def setup_aws_credentials():
    if os.environ.get('AWS_REGION'):
        aws_region = os.environ.get('AWS_REGION')
    else:
        aws_region = 'us-east-1'

    try:
        session = boto3.Session()
        print(f"Successfully connected to {session.region_name}")
    except Exception as e:
        print(f"Failed to connect to AWS: {e}")

# Create an S3 client
def create_s3_client():
    s3 = boto3.client('s3', region_name=aws_region)
    return s3

# Create an S3 bucket
def create_s3_bucket(s3):
    bucket_name = 'my-bucket'
    try:
        s3.create_bucket(Bucket=bucket_name)
        print(f"Bucket {bucket_name} created")
    except Exception as e:
        print(f"Failed to create bucket {bucket_name}: {e}")

# Delete an S3 bucket
def delete_s3_bucket(s3):
    bucket_name = 'my-bucket'
    try:
        s3.delete_bucket(Bucket=bucket_name)
        print(f"Bucket {bucket_name} deleted")
    except Exception as e:
        print(f"Failed to delete bucket {bucket_name}: {e}")

# Upload a file to S3
def upload_file_to_s3(s3, file_path, bucket_name, object_key):
    try:
        s3.upload_file(file_path, bucket_name, object_key)
        print(f"File {file_path} uploaded to {bucket_name}/{object_key}")
    except Exception as e:
        print(f"Failed to upload file {file_path}: {e}")

# Download a file from S3
def download_file_from_s3(s3, bucket_name, object_key, file_path):
    try:
        s3.download_file(bucket_name, object_key, file_path)
        print(f"File {object_key} downloaded to {file_path}")
    except Exception as e:
        print(f"Failed to download file {object_key}: {e}")

# Create an ACL for an S3 bucket
def create_acl(s3, bucket_name):
    acl = {
        'Grantee': {
            'CanonicalUser': 'user1@example.com'
        },
        'Permission': 'READ'
    }
    try:
        s3.put_bucket_policy(Bucket=bucket_name, Policy={'Version': '2012-10-17', 'Statement': [{'Sid': 'AllowReadAccess', 'Effect': 'Allow', 'Principal': {'CanonicalUser': 'user1@example.com'}, 'Action': 's3:GetObject', 'Resource': f'arn:aws:s3:::{bucket_name}/*'}]})
        print(f"Acl created for bucket {bucket_name}")
    except Exception as e:
        print(f"Failed to create acl for bucket {bucket_name}: {e}")

# List bucket policies
def list_bucket_policies(s3, bucket_name):
    try:
        policies = s3.list_bucket_policies(Bucket=bucket_name)
        print(f"Bucket policies for {bucket_name}: {policies['Policies']}")
    except Exception as e:
        print(f"Failed to list bucket policies for {bucket_name}: {e}")

# Monitor usage statistics
def monitor_usage_statistics(s3):
    try:
        stats = s3.get_usage_statistics(
            Bucket='my-bucket',
            Start=1643723400,
            End=1646315200,
            Metric='TotalBytesRead'
        )
        print(f"Usage statistics for bucket: {stats['UsageStatistics'][0]['BytesRead']}")
    except Exception as e:
        print(f"Failed to monitor usage statistics: {e}")

# Main function
def main():
    setup_aws_credentials()
    s3 = create_s3_client()
    bucket_name = 'my-bucket'
    if len(sys.argv) > 1 and sys.argv[1] == 'create':
        create_s3_bucket(s3)
    elif len(sys.argv) > 1 and sys.argv[1] == 'delete':
        delete_s3_bucket(s3)
    elif len(sys.argv) > 1 and sys.argv[1] == 'upload':
        upload_file_to_s3(s3, sys.argv[2], bucket_name, sys.argv[3])
    elif len(sys.argv) > 1 and sys.argv[1] == 'download':
        download_file_from_s3(s3, bucket_name, sys.argv[2], sys.argv[3])
    elif len(sys.argv) > 1 and sys.argv[1] == 'acl':
        create_acl(s3, bucket_name)
    elif len(sys.argv) > 1 and sys.argv[1] == 'list':
        list_bucket_policies(s3, bucket_name)
    elif len(sys.argv) > 1 and sys.argv[1] == 'usage':
        monitor_usage_statistics(s3)

if __name__ == "__main__":
    main()
```

