import warnings
from functools import wraps
import deprecated

def deprecated_decorator(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        warnings.warn(f"{func.__name__} is deprecated. Use {deprecated.get_replacement(func.__name__)} instead.", DeprecationWarning, stacklevel=2)
        return func(*args, **kwargs)
    return wrapper

# Example usage:
@deprecated_decorator
def old_function():
    pass

# To replace with the new function:
from deprecated import replace
replace(old_function, 'new_function')
