import click
import json
import geojson
from geojson import FeatureCollection
import os
import fiona

@click.group()
def geojson_tool():
    pass

@geojson_tool.command()
@click.option('--input', help='Input GeoJSON file')
@click.option('--output', help='Output GeoJSON file')
def geojson_parse(input, output):
    """Parse GeoJSON file."""
    if input and output:
        with open(input, 'r') as f_in, open(output, 'w') as f_out:
            geojson_data = json.load(f_in)
            geojson.dump(geojson_data, f_out, indent=4)
    elif input:
        with open(input, 'r') as f_in:
            geojson_data = json.load(f_in)
            print(geojson_data)
    else:
        click.echo("Please provide input file.")

@geojson_tool.command()
@click.option('--input', help='Input GeoJSON file')
@click.option('--output', help='Output GeoJSON file')
def geojson_render(input, output):
    """Render GeoJSON file."""
    if input and output:
        with open(input, 'r') as f_in, open(output, 'w') as f_out:
            geojson_data = json.load(f_in)
            geojson.render(f_out, geojson_data, show=False)
    elif input:
        with open(input, 'r') as f_in:
            geojson_data = json.load(f_in)
            geojson.render(f_out, geojson_data, show=False)
    else:
        click.echo("Please provide input file.")

@geojson_tool.command()
@click.option('--input', help='Input GeoJSON file')
@click.option('--output', help='Output GeoJSON file')
def geojson_convert(input, output):
    """Convert GeoJSON file."""
    if input and output:
        with open(input, 'r') as f_in, open(output, 'w') as f_out:
            geojson_data = json.load(f_in)
            geojson_data = geojson.convert(geojson_data)
            geojson.dump(geojson_data, f_out, indent=4)
    elif input:
        with open(input, 'r') as f_in:
            geojson_data = json.load(f_in)
            geojson_data = geojson.convert(geojson_data)
            print(geojson_data)
    else:
        click.echo("Please provide input file.")

@geojson_tool.command()
@click.option('--input', help='Input GeoJSON file')
@click.option('--output', help='Output GeoJSON file')
def geojson_fiona(input, output):
    """Convert GeoJSON file to Fiona."""
    if input and output:
        with open(input, 'r') as f_in, open(output, 'w') as f_out:
            geojson_data = json.load(f_in)
            fiona_data = geojson.fiona(geojson_data)
            fiona_data.write(f_out)
    elif input:
        with open(input, 'r') as f_in:
            geojson_data = json.load(f_in)
            fiona_data = geojson.fiona(geojson_data)
            fiona_data.write(f_out)
    else:
        click.echo("Please provide input file.")

@geojson_tool.command()
@click.option('--input', help='Input GeoJSON file')
@click.option('--output', help='Output GeoJSON file')
def geojson_fiona_to_geojson(input, output):
    """Convert Fiona to GeoJSON."""
    if input and output:
        with open(input, 'r') as f_in, open(output, 'w') as f_out:
            fiona_data = fiona.open(f_in)
            geojson_data = geojson.to_geojson(fiona_data)
            geojson.dump(geojson_data, f_out, indent=4)
    elif input:
        with open(input, 'r') as f_in:
            fiona_data = fiona.open(f_in)
            geojson_data = geojson.to_geojson(fiona_data)
            print(geojson_data)
    else:
        click.echo("Please provide input file.")

if __name__ == '__main__':
    geojson_tool()
