import os
import subprocess

class ProcessController:
    def __init__(self, process_name):
        self.process_name = process_name
        self.processes = {}

    def start_process(self):
        if self.process_name in self.processes:
            print(f"Process {self.process_name} is already running.")
            return
        try:
            pid = subprocess.Popen([self.process_name]).pid
            self.processes[self.process_name] = pid
            print(f"Process {self.process_name} started successfully.")
        except Exception as e:
            print(f"Failed to start process {self.process_name}: {e}")

    def stop_process(self):
        if self.process_name not in self.processes:
            print(f"Process {self.process_name} is not running.")
            return
        try:
            os.kill(self.processes[self.process_name], 9)
            del self.processes[self.process_name]
            print(f"Process {self.process_name} stopped successfully.")
        except Exception as e:
            print(f"Failed to stop process {self.process_name}: {e}")

    def restart_process(self):
        self.stop_process()
        self.start_process()

    def get_process_status(self):
        if self.process_name in self.processes:
            try:
                status = subprocess.check_output(['ps', '-p', str(self.processes[self.process_name])], stderr=subprocess.STDOUT).decode('utf-8').strip()
                return status
            except Exception as e:
                print(f"Failed to get process status for {self.process_name}: {e}")
                return None
        else:
            print(f"Process {self.process_name} is not running.")
            return None


# Example usage
if __name__ == "__main__":
    controller = ProcessController('httpd')
    controller.start_process()
    controller.restart_process()
    print(controller.get_process_status())
```

