import unittest
import sys
import pytest
import subprocess

class TestBackportedFeatures(unittest.TestCase):

    def test_keyword_only_args(self):
        with self.assertRaises(TypeError):
            class TestClass:
                def __init__(self, *args, keyword_only_arg):
                    pass
            TestClass(1, keyword_only_arg='test')

    def test_pytest_mark_skip(self):
        @pytest.mark.skip(reason="This test is skipped")
        def test_skip():
            assert False, "This test should not run"

    def test_parallel_run(self):
        if sys.argv[1] != "--parallel":
            self.skipTest("Running tests in parallel requires the --parallel option")

        try:
            subprocess.check_output(["python", "-m", "unittest", "-v"])
        except subprocess.CalledProcessError as e:
            self.fail(f"Failed to run tests in parallel: {e}")

if __name__ == "__main__":
    unittest.main()
