import sympy as sp
import numpy as np

# Define the variable
x = sp.symbols('x')

# Function to evaluate an expression
def evaluate_expression(expr):
    return expr.subs(x, np.linspace(-10, 10, 400)).numpy()

# Function to simplify an expression
def simplify_expression(expr):
    return sp.simplify(expr)

# Function to differentiate an expression
def differentiate_expression(expr):
    return sp.diff(expr, x)

# Function to integrate an expression
def integrate_expression(expr):
    return sp.integrate(expr, x)

# Function to solve an equation
def solve_equation(expr):
    return sp.solve(expr, x)

# Example usage
expr = x**2 + 3*x + 2
print(f"Original expression: {expr}")

simplified_expr = simplify_expression(expr)
print(f"Simplified expression: {simplified_expr}")

derivative = differentiate_expression(expr)
print(f"Derivative: {derivative}")

integral = integrate_expression(expr)
print(f"Integral: {integral}")

solution = solve_equation(expr)
print(f"Solutions: {solution}")
```

```python
import sys
import inspect

class Traceback:
    def __init__(self, tb):
        self.tb = tb

    def __str__(self):
        result = []
        for frame in self.tb:
            result.append(f"{frame.filename}:{frame.lineno} - {frame.function}")
        return '\n'.join(result)

    @staticmethod
    def from_exception(exception):
        return Traceback(inspect.gettrace(exception))

    @staticmethod
    def from_stack(frame):
        return Traceback(inspect.getouterframes(frame))
```

