import ast

def check_pep257(docstrings):
    for node in ast.walk(ast.parse('''
        class TestClass:
            def test_method(self):
                """This is a test method.
                It has multiple lines of documentation.
                """
    ''')):
        if isinstance(node, ast.Expr):
            expr = ast.parse(node.value, mode='eval')
            if isinstance(expr, ast.Expr):
                value = expr.value
                if isinstance(value, ast.Str):
                    doc = value.s
                    if not check_pep257_format(doc):
                        raise ValueError(f"Docstring '{doc}' does not comply with PEP 257 format.")

def check_pep257_format(doc):
    lines = doc.split('\n')
    if len(lines) > 1 and lines[0].strip() == '':
        return False
    if len(lines) < 2 or lines[-1].strip() == '':
        return False
    for line in lines:
        if not line.strip():
            return False
        if not line.strip().endswith('.'):
            return False
    return True

# Test the function
try:
    check_pep257(None)
except ValueError as e:
    print(e)

try:
    check_pep257("This is a test.\n")
except ValueError as e:
    print(e)

try:
    check_pep257("This is a test.\nThis is another test.")
except ValueError as e:
    print(e)

try:
    check_pep257("This is a test.\nThis is another test.\n")
except ValueError as e:
    print(e)
